(2056, 2, '也', 'yě', '<语助>用于句末；表疑问或反问', '何由知吾可<b>也</b>？', '高中必修下册｜《齐桓晋文之事》', '凭什么知道我可以呢？', 0, 0),
(2057, 2, '也', 'yě', '<语助>用于句末；表疑问或反问', '若为佣耕，何富贵<b>也</b>？', '九年级下册｜《陈涉世家》', '你是被雇佣耕地的，哪里来的富贵呢？', 0, 0),
(2058, 2, '也', 'yě', '<语助>用于句末；表祈使', '吾其还<b>也</b>。', '高中必修下册｜《烛之武退秦师》', '我们还是回去吧。', 0, 0),
(2060, 2, '也', 'yě', '<语助>用于句末；表祈使', '不足为外人道<b>也</b>。', '八年级下册｜《桃花源记》', '不值得对外面的人说啊。', 0, 0),
(2061, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '古之圣人，其出人<b>也</b>远矣。', '高中必修上册｜《师说》', '古代的圣人，他们超出一般人很远。', 0, 0),
(2062, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '师道之不传<b>也</b>久矣，欲人之无惑<b>也</b>难矣。', '高中必修上册｜《师说》', '从师学习的风尚不流传，已经很久了；想要人们没有疑惑，很难啊。', 0, 0),
(2063, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '臣之壮<b>也</b>，犹不如人。', '高中必修下册｜《烛之武退秦师》', '我年轻的时候，尚且比不上别人。', 0, 0),
(2064, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '当余之从师<b>也</b>，负箧曳屣，行深山巨谷中。', '九年级下册｜《送东阳马生序》', '当我求学的时候，背着书箱，拖着鞋子，行走在深山大谷之中。', 0, 0),
(2065, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '鹏之徙于南冥<b>也</b>，水击三千里。', '八年级下册｜《北冥有鱼》', '大鹏迁徙到南海的时候，翅膀拍打水面，激起三千里的浪涛。', 0, 0),
(2066, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '大道之行<b>也</b>，天下为公。', '八年级下册｜《大道之行也》', '在大道施行的时候，天下是公共的。', 0, 0),
(2067, 2, '其', 'qí', '<副> 表婉商（祈使商量语气），译为 “还是”', '汝<b>其</b>勿悲！', '高中必修下册｜《与妻书》', '你可不要悲伤！', 0, 0),
(2068, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '食马者不知<b>其</b>能千里而食也。', '八年级下册｜《马说》', '喂马的人不知道它能日行千里，（像普通马一样）喂养它。', 0, 0),
(2069, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '安求<b>其</b>能千里也。', '八年级下册｜《马说》', '怎么能够要求它日行千里呢？', 0, 0),
(2070, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '见<b>其</b>发矢十中八九', '七年级下册｜《马说》', '看见他射箭十支能中八九支。', 0, 0),
(2071, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '若舍郑以为东道主,行李之往来,共<b>其</b>乏困,君亦无所害。', '高中必修下册｜《烛之武退秦师》', '如果饶恕了郑国，并且把它做为东边大道上的主人，出使的人来来往往，（郑国可以随时）供给他们缺少的东西，对您也没有什么害处。', 0, 0),
(2072, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '生乎吾前，<b>其</b>闻道也固先乎吾。', '高中必修上册｜《师说》', '出生在我之前的人，他懂得道理本来就比我早。', 0, 0),
(2073, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '余嘉<b>其</b>能行古道，作《师说》以贻之。', '高中必修上册｜《师说》', '我赞许他能遵从古人从师的风尚，写这篇《师说》来赠送他。', 0, 0),
(2074, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”', '亦各言<b>其</b>志也。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '也各自说说自己的志向。', 0, 0),
(2075, 2, '其', 'qí', '<代>第一人称代词，相当于“我”、“我的”', '失<b>其</b>所与，不知。', '高中必修下册｜《烛之武退秦师》', '失掉自己的同盟者，这是不明智的。', 0, 0),
(2076, 2, '其', 'qí', '<代>指示代词，相当于“那”、“那些”', '<b>其</b>喜洋洋者矣。', '九年级上册｜《岳阳楼记》', '那是喜气洋洋的欢乐景象啊。', 0, 0),
(2077, 2, '其', 'qí', '<代>指示代词，相当于“那”、“那些”', '复前行，欲穷<b>其</b>林。', '八年级上册｜《桃花源记》', '又向前走，想要走到那片林子的尽头。', 0, 0),
(2078, 2, '其', 'qí', '<代>指示代词，相当于“那”、“那些”', '<b>其</b>人视端容寂，若听茶声然。', '八年级下册｜《核舟记》', '那个人目光正视，神色平静，好像在听茶水烧开的声音。', 0, 0),
(2079, 2, '其', 'qí', '<代>指示代词，相当于“其中”、“当中”', '<b>其</b>一犬坐于前。', '七年级上册｜《狼》', '其中一只狼像狗一样蹲坐在前面。', 0, 0),
(2081, 2, '其', 'qí', '<副>难道，岂。表示反诘、反问', '<b>其</b>真无马邪？', '八年级下册｜《马说》', '难道真的没有千里马吗？', 0, 0),
(2083, 2, '其', 'qí', '<副>恐怕；大概。表示推测、估计', '<b>其</b>真不知马也。', '八年级下册｜《马说》', '恐怕是真的不认识千里马啊。', 0, 0),
(2084, 2, '其', 'qí', '<连>如果；假如。表示假设', '<b>其</b>若是，孰能御之？', '高中必修下册｜《齐桓晋文之事》', '如果像这样，谁能够抵挡得住呢？', 0, 0),
(2085, 2, '其', 'qí', '<副>可要。表示期望', '与尔三矢，尔<b>其</b>无忘乃父之志！', '高中选择性必修中册｜《五代伶官传序》', '给你三支箭，你‌千万不要‌忘记你父亲的遗愿！', 0, 0),
(2086, 2, '其', 'qí', '<副>可要。表示期望', '汝<b>其</b>善抚之。', '高中必修下册｜《与妻书》', '你‌可要‌好好抚养他们长大。', 0, 0),
(2087, 2, '乎', 'hū', '<介>相当于“于”；介绍比较对象。译为“与”、“对”、“比”', '异<b>乎</b>三子者之撰。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '和他们三个人的才能（志向）不同。', 0, 0),
(2088, 2, '乎', 'hū', '<助>用在句末，表示感叹', '已矣<b>乎</b>！寓形宇内复几时？', '高中选择性必修下册｜《归去来兮辞并序》', '算了吧！身体寄托在天地间还能有多少时候？', 0, 0),
(2089, 2, '乎', 'hū', '<助>用在句末，表示感叹', '嗟<b>乎</b>！师道之不传也久矣！', '高中必修上册｜《师说》', '唉！古代从师学习的风尚不流传已经很久了！', 0, 0),
(2090, 2, '乎', 'hū', '<助>用在句末，表示感叹', '技盖至此<b>乎</b>！', '高中必修下册｜《庖丁解牛》', '技艺怎么竟然高超到这种地步啊！', 0, 0),
(2091, 2, '乎', 'hū', '<助>用在句中，表示停顿或舒缓', '胡为<b>乎</b>遑遑欲何之？', '高中选择性必修下册｜《归去来兮辞并序》', '', 0, 0),
(2092, 2, '所', 'suǒ', '<助>“所以”：表示行为所凭借的方式、方法或依据', '此臣<b>所</b>以报先帝而忠陛下之职分也。', '九年级下册｜《出师表》', '这是我用来报答先帝、效忠陛下的本分职责。', 0, 0),
(2093, 2, '所', 'suǒ', '<助>“所以”：表示行为所凭借的方式、方法或依据', '<b>所</b>以动心忍性，曾益其<b>所</b>不能。', '八年级下册｜《生于忧患，死于安乐》', '用这些来使他的心受到震撼，使他的性格坚忍起来，增加他所不具备的才干。', 0, 0),
(2094, 2, '所', 'suǒ', '<名>处所；地方', '某<b>所</b>，而母立于兹。', '高中选择性必修下册｜《项脊轩志》', '这个地方，你的母亲曾经站在这里。', 0, 0),
(2095, 2, '所', 'suǒ', '<名>合理的结果；应有的归宿', '必能使行阵和睦，优劣得<b>所</b>。', '九年级下册｜《出师表》', '一定能使军队团结和睦，能力好与差的人都得到合适的位置。', 0, 0),
(2096, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '当其欣于<b>所</b>遇，暂得于己，快然自足。', '高中选择性必修下册｜《兰亭集序》', '当他们对所接触的事物感到高兴时，一时感到自得，快乐满足。', 0, 0),
(2097, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '故列叙时人，录其<b>所</b>述。', '高中选择性必修下册｜《兰亭集序》', '所以一一记下当时在场的人，记录下他们所写下的诗文。', 0, 0),
(2098, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '手之<b>所</b>触，肩之<b>所</b>倚，足之<b>所</b>履，膝之<b>所</b>踦。', '高中必修下册｜《庖丁解牛》', '手接触的地方，肩膀倚靠的地方，脚踩的地方，膝盖抵住的地方。', 0, 0),
(2099, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '今入关，财物无<b>所</b>取，妇女无<b>所</b>幸。', '高中必修下册｜《鸿门宴》', '现在进了关，财物没有取用什么，妇女也没有宠幸谁。', 0, 0),
(2100, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '衣食<b>所</b>安，弗敢专也，必以分人。', '九年级下册｜《曹刿论战》', '衣食这类用来安身的东西，我不敢独自享用，一定把它分给别人。', 0, 0),
(2101, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '必能裨补阙漏，有<b>所</b>广益。', '九年级下册｜《出师表》', '‌一定能弥补缺失和疏漏，带来更大益处‌。', 0, 0),
(2102, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '故余虽愚，卒获有<b>所</b>闻。', '九年级下册｜《送东阳马生序》', '‌所以我虽然愚笨，最终还是能够有所收获。', 0, 0),
(2103, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '问<b>所</b>从来，具答之。', '八年级下册｜《桃花源记》', '‌（渔人）问（他们）从哪里来，（他们）详细地回答了他。', 0, 0),
(2104, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '己<b>所</b>不欲，勿施于人。', '七年级下册｜《〈论语〉十二章》', '‌自己所不愿意的，不要施加给别人。', 0, 0),
(2105, 2, '所', 'suǒ', '<助>与“为”相呼应，构成“为……所……”的被动句式', '为国者无使为积威之<b>所</b>劫哉！', '高中必修下册｜《六国论》', '治理国家的人，千万不要被秦国积久的威势所胁迫啊！', 0, 0),
(2106, 2, '所', 'suǒ', '<助>与“为”相呼应，构成“为……所……”的被动句式', '武父子亡功德，皆为陛下<b>所</b>成就。', '高中选择性必修中册｜《苏武传》', '我苏武父子没有什么功劳恩德，全都是被陛下栽培成全的。', 0, 0),
(2107, 2, '所', 'suǒ', '<助>与“为”相呼应，构成“为……所……”的被动句式', '其印为予群从<b>所</b>得。', '七年级下册｜《活板》', '那些字印被我的堂兄弟侄辈得到。', 0, 0),
(2108, 2, '所', 'suǒ', '<助>“所以”：表示原因，相当于“……的原因、缘故”', '圣人之<b>所</b>以为圣，愚人之<b>所</b>以为愚，其皆出于此乎？', '高中必修上册｜《师说》', '圣人成为圣人的原因，愚人成为愚人的原因，大概都出自这里吧？', 0, 0),
(2109, 2, '所', 'suǒ', '<助>“所以”：表示原因，相当于“……的原因、缘故”', '亲贤臣，远小人，此先汉<b>所</b>以兴隆也；亲小人，远贤臣，此后汉<b>所</b>以倾颓也。', '九年级下册｜《出师表》', '亲近贤臣，疏远小人，这是西汉兴盛的原因；亲近小人，疏远贤臣，这是东汉衰败的原因。', 0, 0),
(2110, 2, '则', 'zé', '<连>表示转折，相当于“却”、“可是”', '臣欲奉诏奔驰，<b>则</b>刘病日笃；欲苟顺私情，<b>则</b>告诉不许。', '高中选择性必修下册｜《陈情表》', '我想要奉命急速赴任，可是祖母刘氏的病一天天加重；想要姑且顺从自己的私情，申诉苦衷却不被允许。', 0, 0),
(2111, 2, '则', 'zé', '<连>表示转折，相当于“却”、“可是”', '余<b>则</b>缊袍敝衣处其间，略无慕艳意。', '八年级下册｜《送东阳马生序》', '我却穿着破旧的衣服处在他们中间，一点也没有羡慕的意思。', 0, 0),
(2112, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '使六国各爱其人，<b>则</b>足以拒秦。', '高中必修下册｜《阿房宫赋》', '假使六国各自爱护它的百姓，那么就足够用来抵抗秦国。', 0, 0),
(2113, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '战<b>则</b>请从。', '九年级下册｜《曹刿论战》', '作战的时候，就请允许我跟随着去。', 0, 0),
(2114, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '居庙堂之高<b>则</b>忧其民；处江湖之远<b>则</b>忧其君。', '九年级上册｜《岳阳楼记》', '在朝廷做官，就为百姓担忧；被贬谪到边远地区做地方官，就为君主担忧。', 0, 0),
(2115, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '春冬之时，<b>则</b>素湍绿潭，回清倒影。', '八年级上册｜《三峡》', '春、冬两个季节，就有白色的急流、碧绿的深潭，回旋的清波倒映着各种景物的影子。', 0, 0),
(2116, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '山不在高，有仙<b>则</b>名。水不在深，有龙<b>则</b>灵。', '八年级下册｜《陋室铭》', '山不在于高，有仙人居住就会出名；水不在于深，有蛟龙潜藏就会显得灵验。', 0, 0),
(2117, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '学而不思<b>则</b>罔，思而不学<b>则</b>殆。', '七年级上册｜《〈论语〉十二章》', '只学习却不思考，就会迷惑；只空想却不学习，就会疑惑。', 0, 0),
(2118, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '淫慢<b>则</b>不能励精，险躁<b>则</b>不能治性。', '七年级上册｜《诫子书》', '放纵懈怠，就不能振奋精神；轻薄浮躁，就不能修养性情。', 0, 0),
(2119, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '日中不至，<b>则</b>是无信；对子骂父，<b>则</b>是无礼。', '七年级上册｜《陈太丘与友期行》', '正午时分没有到，就是不讲信用；对着孩子骂他的父亲，就是没有礼貌。', 0, 0),
(2120, 2, '则', 'zé', '<副>用于加强判断，相当于“乃”、“就是”', '至于斟酌损益，进尽忠言，<b>则</b>攸之、祎、允之任也。', '九年级下册｜《出师表》', '于权衡利弊、兴利除弊，毫无保留地进献忠言，这就是郭攸之、费祎、董允的责任。', 0, 0),
(2122, 2, '焉', 'yān', '<兼词>于此（在这 / 从这 / 于其中）', '积土成山，风雨兴<b>焉</b>；积水成渊，蛟龙生<b>焉</b>。', '高中必修上册｜《劝学》', '积土成为高山，风雨便从这里兴起；积水成为深潭，蛟龙便在这里生长‌。', 0, 0),
(2123, 2, '焉', 'yān', '<兼词>于此（在这 / 从这 / 于其中）', '青麻头伏<b>焉</b>。', '高中选择性必修下册｜《促织》', '那只青麻头蟋蟀趴在那里。', 0, 0),
(2124, 2, '焉', 'yān', '<兼词>于此（在这 / 从这 / 于其中）', '惧有伏<b>焉</b>。', '九年级下册｜《曹刿论战》', '担心在那里有埋伏。', 0, 0),
(2125, 2, '焉', 'yān', '<兼词>于此（在这 / 从这 / 于其中）', '率妻子邑人来此绝境，不复出<b>焉</b>。', '八年级下册｜《桃花源记》', '带领妻子儿女和同乡人来到这个与世隔绝的地方，不再从这里出去。', 0, 0),
(2126, 2, '焉', 'yān', '<助>用于句末，表示疑问或反问，可译为“呢”', '万钟则不辩礼义而受之，万钟于我何加<b>焉</b>！', '九年级下册｜《鱼我所欲也》', '优厚的俸禄如果不分辨礼义就接受，优厚俸禄对我有什么益处呢？', 0, 0),
(2127, 2, '焉', 'yān', '<助>用于句末，表示疑问或反问，可译为“呢”', '肉食者谋之，又何间<b>焉</b>？', '九年级下册｜《曹刿论战》', '当权的人自会谋划这件事，你又何必参与呢？', 0, 0),
(2128, 2, '焉', 'yān', '<助>用于句末，表示陈述语气，相当于“了”、“呢”，常可不译', '可远观而不可亵玩<b>焉</b>。', '八年级下册｜《爱莲说》', '（莲花）只可以远远观赏，不可以靠近玩弄。', 0, 0),
(2129, 2, '焉', 'yān', '<代>表示疑问，相当于“何”，可译作“怎么”、“哪里”', '<b>焉</b>用亡郑以陪邻？', '高中选必修下册｜《烛之武退秦师》', '为什么要灭掉郑国而给邻国增加土地呢？', 0, 0),
(2130, 2, '焉', 'yān', '<代>表示疑问，相当于“何”，可译作“怎么”、“哪里”', '湖中<b>焉</b>得更有此人！', '九年级上册｜《湖心亭看雪》', '在湖中怎么还能碰上这样的人！', 0, 0),
(2132, 2, '以', 'yǐ', '<介>表示动作行为发生的时间、地点，可译为“在”、“从”', '武<b>以</b>始元六年春至京师。', '高中选择性必修中册｜《苏武传》', '苏武在始元六年春天回到京城。', 0, 0),
(2133, 2, '以', 'yǐ', '<介>起提宾作用，可译为“把”', '申之<b>以</b>孝悌之义。', '高中必修下册｜《齐桓晋文之事》', '把孝敬父母、尊敬兄长的道理反复讲给百姓听。', 0, 0),
(2134, 2, '以', 'yǐ', '<介>起提宾作用，可译为“把”', '故临崩寄臣<b>以</b>大事也。', '九年级下册｜《出师表》', '所以临终的时候把国家大事托付给我。', 0, 0),
(2135, 2, '以', 'yǐ', '<连>表目的关系，可译为“而”“来”“用来”等', '斯亦伐根<b>以</b>求木茂，塞源而欲流长者也。', '高中必修下册｜《谏太宗十思疏》', '这也像砍断根却求树木茂盛、堵塞源头却想水流长远。', 0, 0),
(2136, 2, '以', 'yǐ', '<连>表目的关系，可译为“而”“来”“用来”等', '作《师说》<b>以</b>贻之。', '高中必修上册｜《师说》', '写了这篇《师说》来赠送给他。', 0, 0),
(2137, 2, '以', 'yǐ', '<连>表目的关系，可译为“而”“来”“用来”等', '焉用亡郑<b>以</b>陪邻？', '高中必修下册｜《烛之武退秦师》', '为什么要灭掉郑国，来增加邻国的土地呢？', 0, 0),
(2138, 2, '以', 'yǐ', '<连>表目的关系，可译为“而”“来”“用来”等', '<b>以</b>光先帝遗德。', '九年级下册｜《出师表》', '来发扬光大先帝留下的美德。', 0, 0),
(2139, 2, '以', 'yǐ', '<连>表修饰和被修饰关系', '云无心<b>以</b>出岫。', '高中选择性必修下册｜《归去来兮辞并序》', '云朵无心地从山间飘出。', 0, 0),
(2140, 2, '以', 'yǐ', '<连>表修饰和被修饰关系', '俯身倾耳<b>以</b>请。', '九年级下册｜《送东阳马生序》', '弯下身子、侧着耳朵请教。', 0, 0),
(2141, 2, '以', 'yǐ', '<连>表修饰和被修饰关系', '计日<b>以</b>还。', '九年级下册｜《送东阳马生序》', '计算着日子归还。', 0, 0),
(2142, 2, '以', 'yǐ', '<连>表修饰和被修饰关系', '卷石底<b>以</b>出。', '八年级下册｜《小石潭记》', '石底翻卷着露出水面。', 0, 0),
(2143, 2, '以', 'yǐ', '<连>表结果，以致、因而', '不宜妄自菲薄，<b>以</b>塞忠谏之路也。', '九年级下册｜《出师表》', '不应该随便看轻自己，以致堵塞忠臣进谏的道路。', 0, 0),
(2144, 2, '以', 'yǐ', '<助>和 “来” 组成 “以来”，放在时间词后，表示从过去某时直到现在', '自康乐<b>以</b>来，未复有能与其奇者。', '八年级上册｜《答谢中书书》', '自从南朝的谢灵运以来，就再也没有人能够欣赏这种奇丽的山水景色了。', 0, 0),
(2145, 2, '以', 'yǐ', '<动>认为', '自<b>以</b>为大有所益。', '七年级下册｜《孙权劝学》', '自己认为（读书）有很大的好处。', 0, 0),
(2146, 2, '以', 'yǐ', '<连>表示并列或递进关系，可译为“而”、“又”、“并且”等，也可省去', '且硕茂，早实<b>以</b>蕃。', '选择性必修下册｜《种树郭橐驼传》', '（经郭橐驼手种的树）不仅长得高大茂盛，还结果早、果实结得又多。', 0, 0),
(2147, 2, '以', 'yǐ', '<连>表示因果关系，常用在表原因的分句前，可译为“因为”、“由于”', '不<b>以</b>物喜，不<b>以</b>己悲。', '九年级上册｜《岳阳楼记》', '不因外物和自己处境的变化而喜悲。', 0, 0),
(2148, 2, '以', 'yǐ', '<动>通“已”。停止', '毋吾<b>以</b>也。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '不要因为我（年长，就不敢说话）。', 0, 0),
(2149, 2, '何', 'hé', '<代>怎么', '将复<b>何</b>及！', '七年级上册｜《诫子书》', '悔恨又怎么来得及！', 0, 0),
(2150, 2, '何', 'hé', '<代>哪；哪个', '<b>何</b>陋之有？', '八年级下册｜《陋室铭》', '有什么简陋的呢？', 0, 0),
(2151, 2, '何', 'hé', '<副>多么', '至于誓天断发，泣下沾襟，<b>何</b>其衰也！', '高中必修下册｜《六国论》', '到了割下头发、对天发誓，泪水沾湿衣襟的地步，多么衰败啊！', 0, 0),
(2152, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>秦王有虎狼之心，杀人如不能举，刑人如恐不胜。', '高中必修下册｜《鸿门宴》', '秦王有虎狼一样的心肠，杀人惟恐不能杀尽，惩罚人惟恐不能用尽酷刑。', 0, 0),
(2153, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>六国与秦皆诸侯，其势弱于秦。', '高中必修下册｜《六国论》', '六国和秦国都是诸侯国，它们的势力比秦国弱。', 0, 0),
(2154, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>战，勇气也。', '九年级下册｜《曹刿论战》', '作战，靠的是勇气。', 0, 0),
(2155, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>专诸之刺王僚也，彗星袭月。', '九年级下册｜《唐雎不辱使命》', '专诸刺杀吴王僚的时候，彗星的尾巴扫过月亮。', 0, 0),
(2156, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>环而攻之而不胜。', '八年级下册｜《得道多助，失道寡助》', '包围起来攻打它，却不能取胜。', 0, 0),
(2157, 2, '夫', 'fū', '<助>用在句首，引起议论', '<b>夫</b>君子之行，静以修身，俭以养德。', '七年级上册｜《诫子书》', '君子的行为操守，依靠宁静来修养身心，依靠节俭来培养品德。', 0, 0),
(2158, 2, '夫', 'fū', '<代>这；那', '微<b>夫</b>人之力不及此。', '高中必修下册｜《烛之武退秦师》', '假如没有那个人的力量，我是到不了这个地步的。', 0, 0),
(2159, 2, '夫', 'fū', '<代>这；那', '乐<b>夫</b>天命复奚疑？', '高中选择性必修下册｜《归去来兮辞并序》', '以顺随这天命为乐，又有什么可疑虑的呢？', 0, 0),
(2160, 2, '夫', 'fū', '<代>这；那', '予观<b>夫</b>巴陵胜状，在洞庭一湖。', '九年级上册｜《岳阳楼记》', '以顺随这天命为乐，又有什么可疑虑的呢？', 0, 0),
(2161, 2, '夫', 'fū', '<名>成年男子', '遂率子孙荷担者三<b>夫</b>。', '八年级上册｜《愚公移山》', '于是愚公带领儿孙中能挑担子的三个人。', 0, 0),
(2162, 2, '夫', 'fū', '<名>成年男子', '一<b>夫</b>夜呼，乱者四应。', '高中选择性必修中册｜《五代史伶官传序》', '一个人夜里呼喊，作乱的人四方响应。', 0, 0),
(2163, 2, '夫', 'fū', '<助>用在句末，表示感叹', '悲<b>夫</b>！有如此之势，而为秦人积威之所劫。', '高中必修中册｜《六国论》', '可悲啊！有这样有利的形势，却被秦国积久的威势胁迫。', 0, 0),
(2164, 2, '夫', 'fū', '<助>用在句末，表示感叹', '后之视今，亦犹今之视昔，悲<b>夫</b>！', '高中选择性必修下册｜《兰亭集序》', '后人看待今天，也如同今人看待从前一样，可悲啊！', 0, 0),
(2165, 2, '夫', 'fū', '<助>用在句末，表示感叹', '逝者如斯<b>夫</b>，不舍昼夜。', '七年级上册｜《〈论语〉十二章》', '逝去的时光就像这河水一样啊，日夜不停地流去。', 0, 0),
(2166, 2, '与', 'yǔ', '<通假>通“欤“，语气助词，表示疑问、反诘或感叹，相当于“吗”、“吧”、“啊”', '王之所大欲，可得闻<b>与</b>？', '高中必修下册｜《齐桓晋文之事》', '大王最想要的东西，可以说给我听听吗？', 0, 0),
(2167, 2, '与', 'yǔ', '<通假>通“欤“，语气助词，表示疑问、反诘或感叹，相当于“吗”、“吧”、“啊”', '唯求则非邦也<b>与</b>？', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '难道冉求所讲的就不是国家大事吗？', 0, 0),
(2168, 2, '与', 'yǔ', '<通假>通“欤“，语气助词，表示疑问、反诘或感叹，相当于“吗”、“吧”、“啊”', '所识穷乏者得我<b>与</b>？', '九年级下册｜《鱼我所欲也》', '所认识的穷困的人感激我吗？', 0, 0),
(2169, 2, '与', 'yǔ', '<通假>通“欤“，语气助词，表示疑问、反诘或感叹，相当于“吗”、“吧”、“啊”', '轻寡人<b>与</b>？', '九年级下册｜《唐雎不辱使命》', '是轻视我吗？', 0, 0),
(2171, 2, '与', 'yǔ', '<连>表并列，译为和、同', '客亦知夫水<b>与</b>月乎？', '高中必修下册｜《赤壁赋》', '你也知道那江水和月亮吗？', 0, 0),
(2172, 2, '与', 'yǔ', '<连>表并列，译为和、同', '夫六国<b>与</b>秦皆诸侯。', '高中必修下册｜《六国论》', '六国和秦国都是诸侯国。', 0, 0),
(2173, 1, '与', 'yǔ', '<动>给予', '呼尔而<b>与</b>之，行道之人弗受。', '九年级下册｜《鱼我所欲也》', '没有礼貌地吆喝着给他，过路的行人也不肯接受。', 0, 0),
(2174, 2, '与', 'yǔ', '<连>表并列，译为和、同', '太守<b>与</b>客来饮于此。', '九年级上册｜《醉翁亭记》', '太守和宾客来到这里饮酒。', 0, 0),
(2175, 2, '与', 'yǔ', '<连>表并列，译为和、同', '吾<b>与</b>汝毕力平险。', '八年级上册｜《愚公移山》', '我和你们尽全力铲除险峻的大山。', 0, 0),
(2176, 2, '为', 'wèi', '<介>向，对', '<b>为</b>天下唱，宜多应者。', '九年级上册｜《陈涉世家》', '向天下发出号召，应当有很多响应的人。', 0, 0),
(2178, 2, '为', 'wéi', '<动>作为，当作', '以君<b>为</b>长者，故不错意也。', '九年级下册｜《唐雎不辱使命》', '把安陵君当作忠厚长者，所以不打他的主意。', 0, 0),
(2179, 1, '为', 'wéi', '<动>成为；变成', '酿泉<b>为</b>酒，泉香而酒洌。', '九年级上册｜《醉翁亭记》', '用酿泉的水作为酒，泉水香甜，酒水清醇。', 0, 0),
(2180, 2, '为', 'wéi', '<动>作为，当作', '仁以<b>为</b>己任，不亦重乎？', '七年级上册｜《〈论语〉十二章》', '把实现仁德当作自己的责任，不也很重大吗？', 0, 0),
(2181, 1, '为', 'wéi', '<动>成为；变成', '铸以<b>为</b>金人十二。', '高中选择性必修中册｜《过秦论》', '把（兵器）铸造成十二个铜人。', 0, 0),
(2182, 2, '为', 'wéi', '<动>作为，当作', '践华<b>为</b>城，因河<b>为</b>池。', '高中选择性必修中册｜《过秦论》', '凭借华山作为城墙，依托黄河作为护城河。', 0, 0),
(2183, 2, '为', 'wéi', '<动>作为，当作', '据亿丈之城，临不测之渊，以<b>为</b>固。', '高中选择性必修中册｜《过秦论》', '依靠高耸的华山、深不可测的黄河，把它作为坚固的屏障。', 0, 0),
(2184, 2, '为', 'wéi', '<介>为了', '<b>为</b>天下理财，不<b>为</b>征利‌。', '高中必修下册｜《答司马谏议书》', '为天下人治理财政，并不是为自己谋取私利。', 0, 0),
(2185, 2, '为', 'wéi', '<动>是', '宫中府中，俱<b>为</b>一体。', '九年级下册｜《出师表》', '皇宫和丞相府中的官员，都是一个整体。', 0, 0),
(2186, 2, '为', 'wéi', '<动>是', '中峨冠而多髯者<b>为</b>东坡。', '八年级下册｜《核舟记》', '中间戴着高帽子、胡须浓密的人是苏东坡。', 0, 0),
