(2269, 2, '而', 'ér', '<连>表并列', '劳苦<b>而</b>功高如此，未有封侯之赏。', '高中必修下册｜《鸿门宴》', '劳苦功高到这种程度，却没有得到封侯的赏赐。', 0, 0),
(2270, 2, '而', 'ér', '<连>表转折', '此五子者，不产于秦，<b>而</b>穆公用之，并国二十，遂霸西戎。', '高中必修下册｜《谏逐客书》', '这五个人不出生在秦国，秦穆公任用他们，兼并二十个国家，于是称霸西戎。', 0, 0),
(2271, 2, '而', 'ér', '<连>表修饰', '吾扣舷<b>而</b>歌之。', '高中必修上册｜《赤壁赋》', '敲着船边唱起歌来。', 0, 0),
(2272, 2, '而', 'ér', '<连>表修饰', '项王按剑<b>而</b>跽曰。', '高中必修下册｜《鸿门宴》', '敲着船边唱起歌来。', 0, 0),
(2273, 2, '而', 'ér', '<连>表修饰', '河曲智叟笑<b>而</b>止之曰。', '九年级上册｜《愚公移山》', '河曲的智叟笑着劝阻他说。', 0, 0),
(2274, 2, '而', 'ér', '<连>表修饰', '潭西南<b>而</b>望。', '八年级下册｜《小石潭记》', '向小石潭的西南方望去。', 0, 0),
(2275, 2, '而', 'ér', '<连>表修饰', '执策<b>而</b>临之。', '八年级下册｜《马说》', '拿着马鞭面对着千里马。', 0, 0),
(2276, 2, '而', 'ér', '<连>表承接', '余方心动欲还，<b>而</b>大声发于水上。', '高中选择性必修下册｜《石钟山记》', '我正心惊想要回去，这时巨大的声音从水面上传来。', 0, 0),
(2278, 2, '而', 'ér', '<连>表承接', '广起，夺<b>而</b>杀尉。', '九年级下册｜《陈涉世家》', '吴广起身，夺过剑，就杀死了尉官。', 0, 0),
(2279, 2, '而', 'ér', '<连>表承接', '乃记之<b>而</b>去。', '八年级下册｜《小石潭记》', '于是记下这里的景色，就离开了。', 0, 0),
(2280, 2, '而', 'ér', '<连>表承接', '下视其辙，登轼<b>而</b>望之。', '九年级下册｜《曹刿论战》', '（曹刿）下车察看齐军车轮碾过的痕迹，登上车前的横木，然后远望齐军。', 0, 0),
(2281, 2, '而', 'ér', '<连>表承接', '温故<b>而</b>知新，可以为师矣。', '七年级上册｜《〈论语〉十二章》', '温习旧知识，然后能得到新的理解体会，就可以凭这做老师了。', 0, 0),
(2282, 2, '而', 'ér', '<连>表并列', '回视日观以西峰，或得日，或否，绛皜驳色，<b>而</b>皆若偻。', '高中必修上册｜《登泰山记》', '回头看日观峰以西的山峰，有的被日光照到，有的没照到，红白色错杂，而且都像弯腰鞠躬的样子。', 0, 0),
(2283, 2, '而', 'ér', '<连>表递进', '饮少辄醉，<b>而</b>年又最高，故自号曰醉翁也。', '九年级上册｜《醉翁亭记》', '喝很少一点酒就醉了，而且年纪又是最大的，所以给自己取号叫醉翁。', 0, 0),
(2284, 2, '者', 'zhě', '<助>定语后置的标志', '盖简桃核修狭<b>者</b>为之。', '八年级下册｜《核舟记》', '原来是挑选长而窄的桃核雕刻成核舟的。', 0, 0),
(2285, 1, '为', 'wéi', '<动>作为，当作', '蒹葭苍苍，白露<b>为</b>霜。', '八年级下册｜《蒹葭》', '白露凝结成霜。', 0, 0),
(2286, 1, '为', 'wéi', '<动>作为，当作', '<b>为</b>坻，<b>为</b>屿，<b>为</b>嵁，<b>为</b>岩。', '八年级下册｜《小石潭记》', '成为高地、小岛、不平的岩石、石岩。', 0, 0),
(2287, 2, '为', 'wèi', '<介>表示被动', '身死人手，<b>为</b>天下笑者，何也？', '高中选择性必修中册｜《过秦论》', '自身死在别人手里，被天下人耻笑，这是什么缘故呢？', 0, 0),
(2288, 2, '于', 'yú', '<介>介绍动作行为产生的原因，可译为“由于”、“因为”', '生<b>于</b>忧患，死<b>于</b>安乐。', '高中常考虚词｜《进学解》', '忧患使人得以生存发展，安逸享乐使人走向灭亡。', 0, 0),
(2289, 1, '方', 'fāng', '<名>道理；礼义', '石苍黑色，多平<b>方</b>，少圜。', '高中必修上册｜《登泰山记》', '石头是青黑色，大多是平的方形，很少圆形。', 0, 0),
(2290, 1, '方', 'fāng', '<名>方向；方位', '渺渺兮予怀，望美人兮天一<b>方</b>。', '高中必修上册｜《赤壁赋》', '我的情思悠远茫茫，思念心中的美人，她却在天的那一边。', 0, 0),
(2291, 1, '方', 'fāng', '<名>方向；方位', '是以地无四<b>方</b>，民无异国。', '高中必修下册｜《谏逐客书》', '因此土地不分东南西北各个方向，百姓不分本国他国。', 0, 0),
(2293, 1, '方', 'fāng', '<名>方向；方位', '所谓伊人，在水一<b>方</b>。', '八年级下册｜《蒹葭》', '我所思念的那个人，就在河水的那一边。', 0, 0),
(2294, 1, '方', 'fāng', '<名>区域；地方', '今南<b>方</b>已定，兵甲已足。', '九年级下册｜《出师表》', '如今南方这个区域已经平定，武器装备充足。', 0, 0),
(2295, 2, '方', 'fāng', '<介>当；在', '<b>方</b>其系燕父子以组。', '高中选择性必修中册｜《五代史伶官传序》', '当他用绳索捆绑燕王父子的时候。', 0, 0),
(2296, 2, '方', 'fāng', '<介>当；在', '余<b>方</b>心动欲还，而大声发于水上。', '高中选择性必修下册｜《石钟山记》', '我正心惊想要回去，巨大的声音从水面上传来。', 0, 0)
ON DUPLICATE KEY UPDATE
`word_class` = VALUES(`word_class`),
`word` = VALUES(`word`),
`pinyin` = VALUES(`pinyin`),
`meaning` = VALUES(`meaning`),
`example` = VALUES(`example`),
`source` = VALUES(`source`),
`example_trans` = VALUES(`example_trans`),
`status` = VALUES(`status`),
`is_del` = VALUES(`is_del`);

