UPDATE `edu_chn_word_sense` SET `word_class` = 1, `word` = '如', `pinyin` = 'rú', `meaning` = '<动>及、比得上', `example` = '杀人<b>如</b>不能举，刑人<b>如</b>恐不胜。', `source` = '高中必修下册｜《鸿门宴》', `example_trans` = '杀人唯恐不能杀尽，给人施刑唯恐不能用尽。', `status` = 1, `is_del` = 0 WHERE `id` = 127;
