UPDATE `edu_chn_word_sense` SET `word_class` = 2, `word` = '乎', `pinyin` = 'hū', `meaning` = '<助>用在句中，表示停顿或舒缓', `example` = '胡为<b>乎</b>遑遑欲何之？', `source` = '高中选择性必修下册｜《归去来兮辞并序》', `example_trans` = '为什么还要心神不定地想去哪里呢？', `status` = 0, `is_del` = 0 WHERE `id` = 2091;
UPDATE `edu_chn_word_sense` SET `word_class` = 1, `word` = '因', `pinyin` = 'yīn', `meaning` = '<动>依靠，凭借', `example` = NULL, `source` = '高中必修下册｜《谏逐客书》', `example_trans` = '附件将“因”列入《谏逐客书》范围，但当前篇目文本未检出明确用例，暂保留草稿待复核。', `status` = 0, `is_del` = 1 WHERE `id` = 166;
UPDATE `edu_chn_word_sense` SET `word_class` = 1, `word` = '因', `pinyin` = 'yīn', `meaning` = '<动>顺着，依靠', `example` = '诚能见可欲则思知足以自戒，将有作则思知止以安人，念高危则思谦冲而自牧，惧满溢则思江海下百川，乐盘游则思三驱以为度，忧懈怠则思慎始而敬终，虑壅蔽则思虚心以纳下，想谗邪则思正身以黜恶，恩所加则思无<b>因</b>喜以谬赏，罚所及则思无<b>因</b>怒而滥刑。', `source` = '高中必修下册｜《谏太宗十思疏》', `example_trans` = '果真见到想得到的东西就想到知足来自我警戒，将要兴建什么就想到适可而止使百姓安定，想到帝位高危就想到谦虚自我修养，害怕骄傲自满就想到江海处在百川之下，喜爱打猎游乐就想到三驱为度，担心懈怠就想到慎始慎终，忧虑受蒙蔽就想到虚心采纳下属意见，想到有谗邪就想到端正自己来贬黜奸恶，施加恩惠就想到不要因一时高兴而错误奖赏，施加刑罚就想到不要因一时愤怒而滥用刑法。', `status` = 0, `is_del` = 1 WHERE `id` = 180;
UPDATE `edu_chn_word_sense` SET `word_class` = 1, `word` = '行', `pinyin` = 'xíng', `meaning` = '<动>行走', `example` = NULL, `source` = '高中选择性必修下册｜《归去来兮辞并序》', `example_trans` = NULL, `status` = 0, `is_del` = 1 WHERE `id` = 1363;
UPDATE `edu_chn_word_sense` SET `word_class` = 2, `word` = '何', `pinyin` = 'hé', `meaning` = '<副>多么', `example` = '至于誓天断发，泣下沾襟，<b>何</b>其衰也！', `source` = '高中必修下册｜《六国论》', `example_trans` = '到了割下头发、对天发誓，泪水沾湿衣襟的地步，多么衰败啊！', `status` = 0, `is_del` = 1 WHERE `id` = 2151;
