(1291, 2, '之', 'zhī', '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”', '大学<b>之</b>道，在明明德。', '高中选择性必修上册｜《大学之道》', '大学的宗旨在于彰明美德。', 0, 0),
(1292, 2, '而', 'ér', '<连>表承接', '知止<b>而</b>后有定，定<b>而</b>后能静。', '高中选择性必修上册｜《大学之道》', '知道应达到的境界才能志向坚定，志向坚定才能心情安静。', 0, 0),
(1293, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '<b>其</b>所厚者薄，而<b>其</b>所薄者厚，未之有也。', '高中选择性必修上册｜《大学之道》', '所看重的反而薄待，所轻视的反而厚待，这样的事情是没有的。', 0, 0),
(1294, 1, '故', 'gù', '<连>所以', '<b>故</b>有之以为利，无之以为用。', '高中选择性必修上册｜《老子四章》', '所以，有了车毂中间的空处才能发挥车的作用；没有它，车就无法使用。', 0, 0),
(1295, 1, '举', 'jǔ', '<动>举起，提出', '<b>举</b>酒属客，诵明月之诗，歌窈窕之章。', '高中必修上册｜《赤壁赋》', '举起酒杯劝客人饮酒，朗诵《明月》的诗篇，歌唱《窈窕》的篇章。', 1, 0),
(1296, 1, '克', 'kè', '<动>能够，克服', NULL, '高中选择性必修上册｜《老子四章》', NULL, 0, 0),
(1297, 1, '复', 'fù', '<动>返回，复归', '常德不离，<b>复</b>归于婴儿。', '高中选择性必修上册｜《老子四章》', '永恒的德性不离失，复归到婴儿般纯真的状态。', 0, 0),
(1299, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '天下皆知美<b>之</b>为美，斯恶已。', '高中选择性必修上册｜《老子四章》', '天下人都知道美之所以为美，丑就产生了。', 0, 0),
(1300, 2, '其', 'qí', '<代>指示代词，相当于“那”、“那些”', '<b>其</b>安易持，<b>其</b>未兆易谋。', '高中选择性必修上册｜《老子四章》', '局面安定时容易维持，事情没有显露迹象时容易谋划。', 0, 0),
(1301, 1, '属', 'zhǔ', '<动>撰写，连缀', '屈平<b>属</b>草稿未定，上官大夫见而欲夺之。', '高中选择性必修中册｜《屈原列传》', '屈原撰写的草稿还没有定稿，上官大夫看见了就想夺取过来。', 0, 0),
(1302, 1, '志', 'zhì', '<动>记载', '博闻强<b>志</b>，明于治乱，娴于辞令。', '高中选择性必修中册｜《屈原列传》', '见闻广博，记忆力强，明白国家治乱的道理，熟悉外交辞令。', 0, 0),
(1303, 1, '害', 'hài', '<动>嫉妒，损害', '争宠而心<b>害</b>其能。', '高中选择性必修中册｜《屈原列传》', '争夺宠爱而心里嫉妒他的才能。', 0, 0),
(1304, 1, '迁', 'qiān', '<动>放逐，流放', '顷襄王怒而<b>迁</b>之。', '高中选择性必修中册｜《屈原列传》', '顷襄王发怒，把他放逐了。', 0, 0),
(1305, 1, '闻', 'wén', '<动>听闻，见闻', '博<b>闻</b>强志，明于治乱，娴于辞令。', '高中选择性必修中册｜《屈原列传》', '见闻广博，记忆力强，明白国家治乱的道理，熟悉外交辞令。', 0, 0),
(1306, 1, '致', 'zhì', '<动>招致，招来', NULL, '高中选择性必修中册｜《屈原列传》', NULL, 0, 0),
(1307, 1, '见', 'jiàn', '<被动>被，表被动', '信而<b>见</b>疑，忠而被谤，能无怨乎？', '高中选择性必修中册｜《屈原列传》', '诚信却被怀疑，忠贞却被诽谤，能没有怨恨吗？', 0, 0),
(1308, 2, '而', 'ér', '<连>表因果', '故忧愁幽思<b>而</b>作《离骚》。', '高中选择性必修中册｜《屈原列传》', '因此忧愁深思，创作了《离骚》。', 0, 0),
(1309, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '上官大夫见而欲夺<b>之</b>，屈平不与。', '高中选择性必修中册｜《屈原列传》', '上官大夫看见了想要夺取它，屈原不给。', 0, 0),
(1310, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”', '<b>其</b>文约，<b>其</b>辞微，<b>其</b>志洁，<b>其</b>行廉。', '高中选择性必修中册｜《屈原列传》', '他的文章简约，他的文辞含蓄，他的志趣高洁，他的品行正直。', 0, 0),
(1311, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '<b>以</b>一仪而当汉中地，臣请往如楚。', '高中选择性必修中册｜《屈原列传》', '凭张仪一个人就抵得上汉中一带的土地，请让我到楚国去。', 0, 0),
(1312, 1, '固', 'gù', '<形>险固，坚固', '据崤函之<b>固</b>，拥雍州之地。', '高中选择性必修中册｜《过秦论》', '凭借崤山和函谷关的险固，拥有雍州的土地。', 0, 0),
(1313, 1, '务', 'wù', '<动>致力于，从事', '内立法度，<b>务</b>耕织，修守战之具。', '高中选择性必修中册｜《过秦论》', '对内建立法规制度，致力于耕作纺织，修造防守和作战的器械。', 0, 0),
(1314, 1, '修', 'xiū', '<动>修造，整治', '内立法度，务耕织，<b>修</b>守战之具。', '高中选择性必修中册｜《过秦论》', '对内建立法规制度，致力于耕作纺织，修造防守和作战的器械。', 0, 0),
(1316, 1, '致', 'zhì', '<动>招致，招来', '于是从散约败，争割地而赂秦，以<b>致</b>天下之士。', '高中选择性必修中册｜《过秦论》', '于是合纵解散、盟约破裂，争着割让土地贿赂秦国，用来招致天下的士人。', 0, 0),
(1317, 1, '亡', 'wáng', '<动>逃亡的人', '追<b>亡</b>逐北，伏尸百万，流血漂橹。', '高中选择性必修中册｜《过秦论》', '追逐逃亡的败兵，倒下的尸体有百万，流淌的血可以漂浮盾牌。', 0, 0),
(1318, 1, '乘', 'chéng', '<介>趁着，凭借', '因利<b>乘</b>便，宰割天下，分裂山河。', '高中选择性必修中册｜《过秦论》', '凭借有利的形势，割取天下，分割山河。', 0, 0),
(1319, 1, '举', 'jǔ', '<动>攻取，占领', '南取汉中，西<b>举</b>巴蜀，东割膏腴之地，北收要害之郡。', '高中选择性必修中册｜《过秦论》', '向南攻取汉中，向西攻取巴蜀，向东割取肥沃的土地，向北占领险要的郡县。', 0, 0),
(1320, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '<b>以</b>十倍之地，百万之众，叩关而攻秦。', '高中选择性必修中册｜《过秦论》', '凭借十倍于秦的土地、百万军队，攻打函谷关进攻秦国。', 0, 0),
(1322, 2, '之', 'zhī', '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”', '会盟而谋弱秦，不爱珍器重宝肥饶<b>之</b>地，以致天下之士。', '高中选择性必修中册｜《过秦论》', '诸侯举行盟会谋划削弱秦国，不吝惜珍贵器物、重宝和肥沃的土地，来招致天下的士人。', 0, 0),
(1324, 1, '原', 'yuán', '<动>推究根本', '<b>原</b>庄宗之所以得天下，与其所以失之者，可以知之矣。', '高中选择性必修中册｜《五代史伶官传序》', '推究庄宗取得天下的原因，和他失去天下的原因，就可以明白这个道理了。', 0, 0),
(1325, 1, '负', 'fù', '<动>背着', '<b>负</b>而前驱，及凯旋而纳之。', '高中选择性必修中册｜《五代史伶官传序》', '背着箭走在前面，等到凯旋时把箭收藏在太庙。', 0, 0),
(1326, 1, '告', 'gào', '<动>祭告，告知', '则遣从事以一少牢<b>告</b>庙，请其矢。', '高中选择性必修中册｜《五代史伶官传序》', '就派遣属官用猪羊各一头祭告祖庙，请出那三支箭。', 0, 0),
(1327, 1, '抑', 'yì', '<连>还是，或者', '<b>抑</b>本其成败之迹，而皆自于人欤？', '高中选择性必修中册｜《五代史伶官传序》', '还是推究他成功失败的事迹，都由于人为呢？', 0, 0),
(1328, 1, '举', 'jǔ', '<副>全，所有', '故方其盛也，<b>举</b>天下之豪杰，莫能与之争。', '高中选择性必修中册｜《五代史伶官传序》', '所以当他强盛时，全天下的豪杰，没有人能和他抗争。', 0, 0),
(1329, 2, '而', 'ér', '<连>表承接', '世言晋王之将终也，以三矢赐庄宗<b>而</b>告之曰。', '高中选择性必修中册｜《五代史伶官传序》', '世人传说晋王将要去世时，把三支箭赐给庄宗并告诉他说。', 0, 0),
(1330, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”', '<b>其</b>意气之盛，可谓壮哉！', '高中选择性必修中册｜《五代史伶官传序》', '他的意气是多么豪迈，可以说是雄壮啊！', 0, 0),
(1331, 2, '乃', 'nǎi', '<代>你(的)；你们(的)', '尔其无忘<b>乃</b>父之志！', '高中选择性必修中册｜《五代史伶官传序》', '你一定不要忘记你父亲的志向。', 0, 0),
(1332, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '方其系燕父子<b>以</b>组，函梁君臣之首。', '高中选择性必修中册｜《五代史伶官传序》', '当他用丝带捆绑燕王父子，用木匣装着梁国君臣的首级。', 0, 0),
(1333, 1, '除', 'chú', '<动>授予官职', '寻蒙国恩，<b>除</b>臣洗马。', '高中选择性必修下册｜《陈情表》', '不久又蒙受国恩，授予我太子洗马的官职。', 0, 0),
(1334, 1, '拜', 'bài', '<动>授官，任命', '诏书特下，<b>拜</b>臣郎中。', '高中选择性必修下册｜《陈情表》', '诏书特地下达，任命我为郎中。', 0, 0),
(1335, 1, '闵', 'mǐn', '<通假>同“悯”，忧患', '臣以险衅，夙遭<b>闵</b>凶。', '高中选择性必修下册｜《陈情表》', '我因为命运不好，早年遭遇不幸。', 0, 0),
(1336, 1, '鲜', 'xiǎn', '<副>少', '既无伯叔，终<b>鲜</b>兄弟。', '高中选择性必修下册｜《陈情表》', '既没有伯叔，也没有兄弟。', 0, 0),
(1337, 1, '逮', 'dài', '<介>及，等到', '<b>逮</b>奉圣朝，沐浴清化。', '高中选择性必修下册｜《陈情表》', '等到奉行晋朝的圣旨，受到清明的教化。', 0, 0),
(1338, 1, '笃', 'dǔ', '<形>病重', '则刘病日<b>笃</b>。', '高中选择性必修下册｜《陈情表》', '祖母刘氏的病一天比一天严重。', 0, 0),
(1339, 2, '以', 'yǐ', '<介>表示动作行为产生的原因，可译为“因为”、“由于”等', '臣<b>以</b>险衅，夙遭闵凶。', '高中选择性必修下册｜《陈情表》', '我因为命运不好，早年遭遇不幸。', 0, 0),
(1341, 2, '之', 'zhī', '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”', '是臣尽节于陛下<b>之</b>日长。', '高中选择性必修下册｜《陈情表》', '这就是我向陛下尽忠尽节的日子长。', 0, 0),
(1342, 2, '且', 'qiě', '<连>而且；况且；并且。表示递进关系', '<b>且</b>臣少仕伪朝，历职郎署。', '高中选择性必修下册｜《陈情表》', '况且我年轻时曾在伪朝做官，历任郎官。', 0, 0),
(1343, 1, '归', 'guī', '<动>女子出嫁', '后五年，吾妻来<b>归</b>。', '高中选择性必修下册｜《项脊轩志》', '过了五年，我的妻子嫁到我家来。', 0, 0),
(1344, 1, '凡', 'fán', '<副>总共，一共', NULL, '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1345, 1, '再', 'zài', '<副>两次', NULL, '高中选择性必修下册｜《项脊轩志》', NULL, 0, 0),
(1346, 1, '顾', 'gù', '<动>回头看', '每移案，<b>顾</b>视无可置者。', '高中选择性必修下册｜《项脊轩志》', '每次移动书桌，回头看看没有可以安置的地方。', 0, 0),
(1347, 1, '过', 'guò', '<动>超过', '日<b>过</b>午已昏，余叩门扉曰：“吾妻来归。”', '高中选择性必修下册｜《项脊轩志》', '太阳已经过了中午，屋里已经昏暗了，我敲着门说：“我的妻子嫁过来了。”', 0, 0),
(1348, 1, '殆', 'dài', '<副>大概，恐怕', '<b>殆</b>有神护者。', '高中选择性必修下册｜《项脊轩志》', '大概是有神灵在保护吧。', 0, 0),
(1349, 2, '而', 'ér', '<连>表转折', '借书满架，偃仰啸歌，冥然兀坐，万籁有声；<b>而</b>庭有枇杷树，吾妻死之年所手植也。', '高中选择性必修下册｜《项脊轩志》', '借来的书摆满书架，我时而俯仰时而长啸歌唱，静默地独自端坐，万物的声音都能听到；庭院里有一棵枇杷树，是我妻子去世那年亲手种的。', 0, 0),
(1350, 2, '之', 'zhī', '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”', '先是，庭有枇杷树，吾妻死<b>之</b>年所手植也。', '高中选择性必修下册｜《项脊轩志》', '这以前，庭院里有一棵枇杷树，是我妻子去世那年亲手种的。', 0, 0),
(1351, 2, '其', 'qí', '<代>指示代词，相当于“那”、“那些”', '<b>其</b>后六年，吾妻死；<b>其</b>后二年，余久卧病无聊。', '高中选择性必修下册｜《项脊轩志》', '又过了六年，我的妻子去世；又过了两年，我长久卧病无聊。', 0, 0),
(1352, 1, '修', 'xiū', '<形>高，高长', '此地有崇山峻岭，茂林<b>修</b>竹。', '高中选择性必修下册｜《兰亭集序》', '这里有高峻的山岭、高大的树林和修长的竹子。', 0, 0),
(1353, 1, '次', 'cì', '<名>旁边，水边', '列坐其<b>次</b>。', '高中选择性必修下册｜《兰亭集序》', '大家排列坐在曲水旁边。', 0, 0),
(1354, 1, '期', 'qī', '<动>至，及', '况修短随化，终<b>期</b>于尽！', '高中选择性必修下册｜《兰亭集序》', '何况人的寿命长短听凭造化，最终归结于消灭。', 0, 0),
(1355, 1, '致', 'zhì', '<名>情趣，情致', '虽世殊事异，所以兴怀，其<b>致</b>一也。', '高中选择性必修下册｜《兰亭集序》', '虽然时代不同、事情不同，但人们产生感慨的原因和情趣是一样的。', 0, 0),
(1356, 1, '信', 'xìn', '<副>确实，实在', '<b>信</b>可乐也。', '高中选择性必修下册｜《兰亭集序》', '确实值得快乐啊。', 0, 0),
(1357, 2, '之', 'zhī', '<助>用在定语和中心词之间，表示修饰、领属的关系，相当于“的”', '会于会稽山阴<b>之</b>兰亭，修禊事也。', '高中选择性必修下册｜《兰亭集序》', '在会稽山阴的兰亭聚会，举行修禊这种活动。', 0, 0),
(1359, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）”、“它”、“他们”', '当<b>其</b>欣于所遇，暂得于己，快然自足，不知老之将至。', '高中选择性必修下册｜《兰亭集序》', '当他们对所接触的事物感到高兴，一时感到自得，感到快乐和满足，竟不知道老年将要到来。', 0, 0),
(1360, 2, '以', 'yǐ', '<介>起提宾作用，可译为“把”', '引<b>以</b>为流觞曲水，列坐其次。', '高中选择性必修下册｜《兰亭集序》', '把水引来作为漂流酒杯的曲水，大家排列坐在曲水旁边。', 0, 0),
(1361, 1, '谏', 'jiàn', '<动>挽回，劝止', '悟已往之不<b>谏</b>，知来者之可追。', '高中选择性必修下册｜《归去来兮辞并序》', '认识到过去的事情已经无法挽回，知道未来的日子还可以补救。', 0, 0),
(1362, 1, '追', 'zhuī', '<动>补救，挽救', '悟已往之不谏，知来者之可<b>追</b>。', '高中选择性必修下册｜《归去来兮辞并序》', '认识到过去的事情已经无法挽回，知道未来的日子还可以补救。', 0, 0),
(1363, 1, '行', 'xíng', '<动>行走', NULL, '高中选择性必修下册｜《归去来兮辞并序》', NULL, 0, 0),
(1364, 1, '善', 'shàn', '<动>喜欢，羡慕', NULL, '高中选择性必修下册｜《归去来兮辞并序》', NULL, 0, 0),
(1365, 1, '乘', 'chéng', '<动>顺应，顺着', '聊<b>乘</b>化以归尽，乐夫天命复奚疑！', '高中选择性必修下册｜《归去来兮辞并序》', '姑且顺应自然的变化走到生命的尽头，乐于听从天命还有什么疑虑呢？', 0, 0),
(1366, 2, '而', 'ér', '<连>表转折', '门虽设<b>而</b>常关。', '高中选择性必修下册｜《归去来兮辞并序》', '门虽然设置了却经常关闭。', 0, 0),
(1367, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '悟已往<b>之</b>不谏，知来者<b>之</b>可追。', '高中选择性必修下册｜《归去来兮辞并序》', '认识到过去的事情已经无法挽回，知道未来的日子还可以补救。', 0, 0),
(1368, 2, '以', 'yǐ', '<连>表修饰和被修饰关系', '木欣欣<b>以</b>向荣，泉涓涓而始流。', '高中选择性必修下册｜《归去来兮辞并序》', '树木欣欣向荣，泉水涓涓开始流淌。', 0, 0),
(1370, 1, '本', 'běn', '<名>根本，根', '凡植木之性，其<b>本</b>欲舒，其培欲平。', '高中选择性必修下册｜《种树郭橐驼传》', '大凡种植树木的特性是，它的根要舒展，培土要平。', 0, 0),
(1371, 1, '顺', 'shùn', '<动>顺应，遵循', '能<b>顺</b>木之天，以致其性焉尔。', '高中选择性必修下册｜《种树郭橐驼传》', '能够顺应树木的天性，来使它的本性得到充分发展罢了。', 0, 0),
(1372, 1, '致', 'zhì', '<动>使……达到', '能顺木之天，以<b>致</b>其性焉尔。', '高中选择性必修下册｜《种树郭橐驼传》', '能够顺应树木的天性，来使它的本性得到充分发展罢了。', 0, 0),
(1373, 1, '顾', 'gù', '<动>回头看', '已去而复<b>顾</b>，甚者，爪其肤以验其生枯。', '高中选择性必修下册｜《种树郭橐驼传》', '已经离开了又回头看，更严重的还要抓破树皮来检查它是活着还是枯死。', 0, 0),
(1374, 1, '故', 'gù', '<连>所以，因此', '<b>故</b>吾不害其长而已，非有能硕茂之也。', '高中选择性必修下册｜《种树郭橐驼传》', '所以我不妨害它的生长罢了，并不是有能力使它硕大茂盛。', 0, 0),
(1375, 2, '而', 'ér', '<连>表承接', '旦视<b>而</b>暮抚，已去<b>而</b>复顾。', '高中选择性必修下册｜《种树郭橐驼传》', '早晨去看它，晚上去抚摸它，已经离开了又回头看。', 0, 0),
(1376, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '故乡人号<b>之</b>“驼”。', '高中选择性必修下册｜《种树郭橐驼传》', '所以乡里人给他取名叫“橐驼”。', 0, 0),
(1377, 2, '其', 'qí', '<代>第三人称代词。相当于“他（她）的”、“它的”、“他们的”', '<b>其</b>土欲故，<b>其</b>筑欲密。', '高中选择性必修下册｜《种树郭橐驼传》', '它的土要用原来的土，培土要捣得结实。', 0, 0),
(1378, 1, '适', 'shì', '<动>到……去', '余自齐安舟行<b>适</b>临汝。', '高中选择性必修下册｜《石钟山记》', '我从齐安坐船到临汝去。', 0, 0),
(1379, 1, '察', 'chá', '<动>观察，考察', '徐而<b>察</b>之，则石之铿然有声者，所在皆是也。', '高中选择性必修下册｜《石钟山记》', '慢慢地观察它，才发现能发出铿锵声音的石头，到处都是这样。', 0, 0),
(1380, 1, '向', 'xiàng', '<副>先前，原来', NULL, '高中选择性必修下册｜《石钟山记》', NULL, 0, 0),
(1381, 1, '绝', 'jué', '<形>陡峭的，险峻的', '士大夫终不肯以小舟夜泊<b>绝</b>壁之下。', '高中选择性必修下册｜《石钟山记》', '士大夫始终不愿意乘小船在夜里停泊在陡峭的山崖下面。', 0, 0),
(1382, 1, '当', 'dāng', '<动>在，处于', NULL, '高中选择性必修下册｜《石钟山记》', NULL, 0, 0),
(1383, 1, '记', 'jì', '<动>记述，记录', NULL, '高中选择性必修下册｜《石钟山记》', NULL, 0, 0),
(1384, 2, '而', 'ér', '<连>表承接', '扣<b>而</b>聆之，南声函胡，北音清越，桴止响腾，余韵徐歇。', '高中选择性必修下册｜《石钟山记》', '敲击并倾听它，南边的声音含糊，北边的声音清脆悠扬，鼓槌停止了，声音还在传播，余音慢慢消失。', 0, 0),
(1385, 2, '之', 'zhī', '<助>定语后置的标志', '石<b>之</b>铿然有声者，所在皆是也。', '高中选择性必修下册｜《石钟山记》', '能发出铿锵声音的石头，到处都是这样。', 0, 0),
(1386, 2, '其', 'qí', '<代>指示代词，相当于“其中”、“当中”', '于乱石间择<b>其</b>一二扣之。', '高中选择性必修下册｜《石钟山记》', '在乱石中选择其中的一两块敲击它。', 0, 0),
(1387, 2, '焉', 'yān', '<兼词>于此（在这 / 从这 / 于其中）', '而人之所罕至<b>焉</b>，故非有志者不能至也。', '高中选择性必修下册｜《石钟山记》', '而人很少到达那里，所以没有志向的人是不能到达的。', 0, 0),
(1389, 2, '而', 'ér', '<连>表并列', '剑阁峥嵘<b>而</b>崔嵬，一夫当关，万夫莫开。', '高中常考虚词｜《蜀道难》', '剑阁高峻崎岖而崔嵬险要，一人把守关口，万人也难以攻破。', 0, 0),
(1390, 2, '而', 'ér', '<连>表递进', '君子博学<b>而</b>日参省乎己。', '高中必修上册｜《劝学》', '君子广泛学习并且每天检查反省自己，就能智慧明达、行为没有过错。', 0, 0),
(1391, 2, '而', 'ér', '<连>表递进', '楚怀王贪<b>而</b>信张仪，遂绝齐。', '高中选择性必修中册｜《屈原列传》', '楚怀王贪图利益而且相信张仪，于是同齐国断绝了关系。', 0, 0),
(1392, 2, '而', 'ér', '<连>表承接', '置之地，拔剑撞<b>而</b>破之', '高中必修下册｜《鸿门宴》', '把玉斗放在地上，拔出剑撞击它，把它击破了。', 0, 0),
(1394, 2, '而', 'ér', '<连>表转折', '有如此之势，<b>而</b>为秦人积威之所劫', '高中必修下册｜《六国论》', '却有这样的形势，仍被秦国积久的威势所胁迫。', 0, 0),
(1400, 2, '而', 'ér', '<连>表因果', '表恶其能<b>而</b>不用也。', '高中常考虚词｜《赤壁之战》', '曹操嫉妒他的才能因此不任用他。', 0, 0),
(1401, 2, '而', 'ér', '<连>表目的', '缦立远视，<b>而</b>望幸焉', '高中必修下册｜《阿房宫赋》', '（宫女们）久久站立，远远眺望，盼望皇帝到来、宠幸自己。', 0, 0),
(1402, 2, '而', 'ér', '<连>表目的', '籍吏民，封府库，<b>而</b>待将军。', '高中必修下册｜《鸿门宴》', '登记官吏和百姓，封闭官府仓库，来等待将军。', 0, 0),
(1404, 2, '而', 'ér', '<通假>同 “尔”，第二人称代词，你，你的', '某所，<b>而</b>母立于兹。', '高中选择性必修下册｜《项脊轩志》', '某个地方，你的母亲曾经站在这里。', 0, 0),
(1410, 2, '而', 'ér', '<连>表递进', '臣虽下愚，知其不可，<b>而</b>况于明哲乎？', '高中必修下册｜《谏太宗十思疏》', '我虽然是最愚笨的人，也知道这样做不对，何况明智的人呢？', 0, 0),
(1414, 2, '何', 'hé', '<代>为什么', '齐人未尝赂秦，终继五国迁灭，<b>何</b>哉？', '高中必修下册｜《六国论》', '齐国不曾贿赂秦国，最终也随着五国灭亡，为什么呢？', 0, 0),
(1415, 2, '何', 'hé', '<代>什么', '大王来<b>何</b>操？', '高中必修下册｜《鸿门宴》', '大王来的时候带了什么东西？', 0, 0),
(1418, 2, '何', 'hé', '<代>哪；哪个', '然则<b>何</b>时而乐耶？', '九年级上册｜《岳阳楼记》', '那么什么时候才快乐呢？', 0, 0),
(1420, 2, '何', 'hé', '<代>怎么', '徐公<b>何</b>能及君也？', '九年级下册｜《邹忌讽齐王纳谏》', '徐公怎么能比得上您呢？', 0, 0),
(1421, 2, '何', 'hé', '<副>多么', '至于誓天断发，泣下沾襟，<b>何</b>其衰也！', '高中选择性必修中册｜《五代史伶官传序》', '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！', 0, 0),
(1425, 2, '何', 'hé', '<代>为什么', '沛公大惊，曰：“为之奈<b>何</b>？”', '高中必修下册｜《鸿门宴》', '刘邦大吃一惊，说：“这件事怎么办呢？”', 0, 0),
(1426, 2, '何', 'hé', '<代>什么', '一旦山陵崩，长安君<b>何</b>以自托于赵？', '高中常考虚词｜《触龙说赵太后》', '一旦太后去世，长安君将凭什么在赵国托身呢？', 0, 0),
(1427, 2, '何', 'hé', '<代>什么', '不为者与不能者之形<b>何</b>以异？', '高中必修下册｜《齐桓晋文之事》', '不去做和不能做的情形有什么不同呢？', 0, 0),
(1428, 2, '何', 'hé', '<代>什么', '抚军不忘所自，无<b>何</b>，宰以卓异闻，宰悦，免成役。', '高中必修下册｜《促织》', '巡抚没有忘记成名的来历，不久，县令便因他的才能出众而听闻于上级，县令很高兴，免除了成名的差役。', 0, 0),
(1430, 2, '乎', 'hū', '<助>用在句末，表示疑问或反问', '儿寒<b>乎</b>？欲食<b>乎</b>？', '高中选择性必修下册｜《项脊轩志》', '天气有点冷吗？想吃东西吗？', 0, 0),
(1431, 2, '乎', 'hū', '<助>用在句末，表示疑问或反问', '欲安所归<b>乎</b>？', '高中常考虚词｜《赤壁之战》', '想要到哪里去归附呢？', 0, 0),
(1432, 2, '乎', 'hū', '<助>用在句末，表示疑问或反问', '布衣之交尚不相欺，况在国<b>乎</b>？', '高中必修下册｜《鸿门宴》', '平民之间的交往尚且不互相欺骗，何况在国家之间呢？', 0, 0),
(1433, 2, '乎', 'hū', '<助>用在句末，表示疑问或反问', '王候将相另有种<b>乎</b>?', '九年级下册｜《陈涉世家》', '‌那些称王侯拜将相的人，难道是天生的的贵种吗？', 0, 0),
(1435, 2, '乎', 'hū', '<助>用在句末，表示疑问或反问', '今亡亦死，举大计亦死，等死，死国可<b>乎</b>？', '九年级下册｜《陈涉世家》', '现在逃亡也是死，发动大事也是死，同样是死，为国事而死可以吗？', 0, 0),
(1436, 2, '乎', 'hū', '<助>用在句末，表示感叹', '宜<b>乎</b>百姓之谓我爱也。', '高中必修下册｜《齐桓晋文之事》', '看来百姓认为我吝啬是适宜的了。', 0, 0),
(1437, 2, '乎', 'hū', '<助>用在句末，表示感叹', '西望夏口，东望武昌，山川相缪，郁<b>乎</b>苍苍', '高中必修上册｜《赤壁赋》', '向西望是夏口，向东望是武昌，山水相互缭绕，草木郁郁苍苍。', 0, 0),
(1439, 2, '乎', 'hū', '<介>相当于“于”；介绍处所、方向、时间。译为“在”、“由”等', '醉翁之意不在酒，在<b>乎</b>山水之间也。', '高中常考虚词｜《岳阳楼记》', '醉翁的情趣不在酒上，而在山水之间。', 0, 0),
(1441, 2, '乎', 'hū', '<介>相当于“于”；介绍处所、方向、时间。译为“在”、“由”等', '生<b>乎</b>吾前。', '高中必修上册｜《师说》', '出生在我前面的人。', 0, 0),
(1442, 2, '乎', 'hū', '<介>相当于“于”；介绍比较对象。译为“与”、“对”、“比”', '君子博学而日参省<b>乎</b>己。', '高中选择性必修上册｜《论语》', '君子广泛学习并且每天检查反省自己。', 0, 0),
(1446, 2, '乎', 'hū', '<词缀>用于形容词、叠音词后面', '以无厚入有间，恢恢<b>乎</b>其于游刃必有余地矣', '高中必修下册｜《庖丁解牛》', '用没有厚度的刀刃插入有间隙的骨节，刀刃游动起来宽绰有余。', 0, 0),
(1447, 2, '乎', 'hū', '<词缀>用于形容词、叠音词后面', '浩浩<b>乎</b>如冯虚御风，而不知其所止；飘飘<b>乎</b>如遗世独立，羽化而登仙。', '高中必修上册｜《赤壁赋》', '浩浩荡荡仿佛凌空乘风而行，不知停在哪里；飘飘然像脱离尘世、独立存在，飞升成仙。', 0, 0),
(1449, 2, '乃', 'nǎi', '<副>才', '度我至军中，公<b>乃</b>入。', '高中必修下册｜《鸿门宴》', '估计我已经回到军营，您才进去。', 0, 0),
(1450, 2, '乃', 'nǎi', '<副>竟然；却', '问今是何世，<b>乃</b>不知有汉。', '高中常考虚词｜《桃花源记》', '问现在是什么朝代，竟然不知道有汉朝，更不必说魏朝和晋朝了。', 0, 0),
(1451, 2, '乃', 'nǎi', '<副>竟然；却', '今其智<b>乃</b>反不能及。', '高中必修上册｜《师说》', '现在他们的智慧反而赶不上这些人。', 0, 0),
(1456, 2, '乃', 'nǎi', '<代>这；这样', '夫我<b>乃</b>行之，反而求之，不得吾心。', '高中必修下册｜《齐桓晋文之事》', '可是我这样做了以后，反过来再寻求这样做的原因，却不明白自己的心意。', 0, 0),
(1459, 2, '乃', 'nǎi', '<代>这；这样', '府吏再拜还，长叹空房中，作计<b>乃</b>尔立。', '高中常考虚词｜《孔雀东南飞》', '府吏拜了两拜回去，在空房中长叹，打定主意的计划才这样确定下来。', 0, 0),
(1468, 2, '其', 'qí', '<副>可要。表示期望', '安陵君<b>其</b>许寡人！', '九年级下册｜《唐雎不辱使命》', '安陵君，你可要答应我啊！', 0, 0),
(1469, 2, '其', 'qí', '<副> 表婉商（祈使商量语气），译为 “还是”', '攻之不克，围之不继，吾<b>其</b>还也。', '高中必修下册｜《烛之武退秦师》', '进攻不能取胜，包围又没有后援，我们还是回去吧。', 0, 0),
(1470, 2, '其', 'qí', '<副>恐怕；大概。表示推测、估计', '圣人之所以为圣，愚人之所以为愚，<b>其</b>皆出于此乎？', '高中必修上册｜《师说》', '圣人之所以成为圣人、愚人之所以成为愚人，大概都出于这个原因吧？', 0, 0),
(1472, 2, '其', 'qí', '<副>难道，岂。表示反诘、反问', '以残年余力，曾不能毁山之一毛，<b>其</b>如土石何？', '高中必修上册｜《愚公移山》', '凭我残余的年岁和力量，连山上的一根草木都不能毁掉，能把土石怎么样呢？', 0, 0),
(1475, 2, '其', 'qí', '<连>如果；假如。表示假设', '<b>其</b>业有不精，德有不成者，非天质之卑，则心不若余之专耳。', '九年级下册｜《送东阳马生序》', '如果他的学业有不精通、品德有不成就的地方，不是天资低下，就是用心不如我专一。', 0, 0),
(1477, 2, '其', 'qí', '<副>难道，岂。表示反诘、反问', '至于誓天断发，泣下沾襟，何<b>其</b>衰也!', '高中选择性必修中册｜《五代伶官传序》', '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！', 0, 0),
(1480, 2, '且', 'qiě', '<连>而且；况且；并且。表示递进关系', '<b>且</b>壮士不死即已，死即举大名耳。', '高中常考虚词｜《陈涉世家》', '况且壮士不死就罢了，死了就要成就大的名声。', 0, 0),
(1481, 2, '且', 'qiě', '<连>而且；况且；并且。表示递进关系', '<b>且</b>燕赵处秦革灭殆尽之际。', '高中必修下册｜《六国论》', '况且燕、赵两国正处在秦国变法改革、几乎灭亡的时刻。', 0, 0),
(1482, 2, '且', 'qiě', '<副>尚；尚且', '臣死<b>且</b>不避，卮酒安足辞！', '高中必修下册｜《鸿门宴》', '我连死都不躲避，一杯酒哪里值得推辞！', 0, 0),
(1483, 2, '且', 'qiě', '<副>尚；尚且', '故之圣人，其出人也远矣，犹<b>且</b>从师而问焉。', '高中必修上册｜《师说》', '所以古代的圣人，他们远远超过一般人，尚且跟从老师请教。', 0, 0),
(1485, 2, '且', 'qiě', '<连>又；一边……一边。表示并列关系', '命如南山石，四体康<b>且</b>直。', '高中选择性必修中册｜《孔雀东南飞并序》', '寿命像南山的石头一样长，身体健康而且挺直。', 0, 0),
(1490, 2, '且', 'qiě', '<连>而且；况且；并且。表示递进关系', '<b>且</b>夫天下非小弱也，雍州之地，肴函之固，自若也。', '高中选择性必修中册｜《过秦论》', '况且天下并没有缩小削弱，雍州的土地、崤山函谷关的险固，仍然和原来一样。', 0, 0),
(1491, 2, '且', 'qiě', '<连>而且；况且；并且。表示递进关系', '<b>且</b>夫天地之间，物各有主。', '高中必修上册｜《赤壁赋》', '况且天地之间，万物各有自己的主人。', 0, 0),
(1493, 1, '若', 'ruò', '<动>像', '视之，形<b>若</b>土狗，梅花翅，方首，长胫，意似良。', '高中必修下册｜《促织》', '看它的形状像土狗，长着梅花斑的翅膀，方头、长腿，心里认为它似乎是上好的。', 0, 0),
(1494, 1, '若', 'ruò', '<动>像', '吾不忍其觳觫，<b>若</b>无罪而就死地。', '高中必修下册｜《齐桓晋文之事》', '我不忍心看它恐惧战栗，像没有罪却走向死地一样。', 0, 0),
(1495, 2, '若', 'ruò', '<代>你；你们；你(们)的', '<b>若</b>入前为寿，寿毕，请以剑舞。', '高中必修下册｜《鸿门宴》', '你进去上前敬酒，敬完酒，请求用剑起舞。', 0, 0),
(1496, 2, '若', 'ruò', '<代>你；你们；你(们)的', '不者，<b>若</b>属皆且为所虏。', '高中必修下册｜《鸿门宴》', '否则你们这些人都将被他俘虏。', 0, 0),
(1497, 2, '若', 'ruò', '<代>这样的；这', '以<b>若</b>所为求<b>若</b>所欲，犹缘木而求鱼也。', '高中必修下册｜《齐桓晋文之事》', '凭着这样的做法，去追求这想要的东西。', 0, 0),
(1502, 2, '若', 'ruò', '<连>至于', '<b>若</b>民，则无恒产，因无恒心。', '高中必修下册｜《齐桓晋文之事》', '至于百姓，如果没有固定的产业，就没有长久不变的心。', 0, 0),
(1508, 2, '所', 'suǒ', '<名>处所；地方', '又间令吴广之次<b>所</b>旁丛祠中。', '九年级下册｜《陈涉世家》', '又暗中让吴广到驻地旁边的丛林祠堂里去。', 0, 0),
(1509, 2, '所', 'suǒ', '<名>处所；地方', '成反复自念，得无教我猎虫<b>所</b>耶？', '高中必修下册｜《促织》', '成反复思考，莫非是教我寻找蟋蟀的地方吗？', 0, 0),
(1510, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '道之<b>所</b>存，师之<b>所</b>存也。', '高中必修上册｜《师说》', '道理存在的地方，就是老师存在的地方。', 0, 0),
(1511, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '过蒙拔擢，宠命优渥，岂敢盘桓，有<b>所</b>希冀', '高中选择性必修下册｜《陈情表》', '过分承蒙提拔，恩命优厚，哪里敢徘徊不前，还有什么希望呢？', 0, 0),
(1519, 2, '所', 'suǒ', '<助>“所以”：表示原因，相当于“……的原因、缘故”', '<b>所</b>以遣将守关者，备他盗之出入与非常也。', '高中必修下册｜《鸿门宴》', '派遣将领把守函谷关的原因，是防备其他盗贼的进入和意外的变故。', 0, 0),
(1520, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '此<b>所</b>谓战胜于朝廷。', '高中常考虚词｜《邹忌讽齐王纳谏》', '这就是所说的在朝廷上战胜别国。', 0, 0),
(1521, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '非吾<b>所</b>谓传其道解其惑者也。', '高中必修上册｜《师说》', '不是我所说的传授道理、解答疑惑的老师。', 0, 0),
(1522, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '石之铿然有声音者，<b>所</b>在皆是也。', '高中选择性必修下册｜《石钟山记》', '石头敲击时发出铿锵声音的地方，到处都是这样。', 0, 0),
(1524, 2, '所', 'suǒ', '<代>放在动词或动短语前，组成名词性短语，表示“……的地方”、“……的人”、“……的事物”等', '急趋之，折过墙隅，迷其<b>所</b>在。', '高中必修下册｜《促织》', '急忙追赶它，转过墙角，迷失了它所在的地方。', 0, 0),
(1525, 2, '为', 'wéi', '<动>作为，当作', '斩木<b>为</b>兵，揭竿<b>为</b>旗。', '高中选择性必修中册｜《过秦论》', '砍下树木当作兵器，举起竹竿当作旗帜。', 0, 0),
(1526, 2, '为', 'wéi', '<动>作为，当作', '然后以六合<b>为</b>家，崤函<b>为</b>宫。', '高中选择性必修中册｜《过秦论》', '然后把天下作为家，把崤山函谷关作为宫殿。', 0, 0),
(1528, 2, '为', 'wéi', '<动>成为；变成', '冰，水<b>为</b>之，而寒于水。', '高中必修上册｜《劝学》', '冰是水凝结而成的，却比水更寒冷。', 0, 0),
(1531, 2, '为', 'wéi', '<动>作为，当作', '南取百越之地，以<b>为</b>桂林、象郡。', '高中选择性必修中册｜《过秦论》', '向南夺取百越的土地，把它设置为桂林郡和象郡。', 0, 0),
(1534, 2, '为', 'wéi', '<动>以为；认为', '两小儿笑曰：“孰<b>为</b>汝多知乎！”', '高中常考虚词｜《两小儿辩日》', '两个小孩笑着说：“谁说你知道得多呢？”', 0, 0),
(1535, 2, '为', 'wéi', '<动>是', '如今人方<b>为</b>刀俎，我<b>为</b>鱼肉。', '高中必修下册｜《鸿门宴》', '如今别人正是刀和砧板，我们正是鱼和肉。', 0, 0),
(1536, 2, '为', 'wéi', '<动>是', '非<b>为</b>织作迟。', '高中选择性必修下册｜《孔雀东南飞并序》', '不是因为织布缓慢。', 0, 0),
(1537, 2, '为', 'wèi', '<介>表示被动', '吾属今<b>为</b>之虏矣。', '高中必修下册｜《鸿门宴》', '我们这些人现在要被他俘虏了。', 0, 0),
(1538, 2, '为', 'wèi', '<介>表示被动', '身死国灭，<b>为</b>天下笑。', '高中选择性必修中册｜《五代史伶官传序》', '自身死去，国家灭亡，被天下人耻笑。', 0, 0),
(1539, 2, '为', 'wèi', '<介>表示被动', '不者，若属皆且<b>为</b>所虏。', '高中必修下册｜《鸿门宴》', '否则你们这些人都将被他俘虏。', 0, 0),
(1541, 2, '为', 'wèi', '<介>因为', '慎勿<b>为</b>归死，贵贱轻何薄！', '高中选择性必修下册｜《孔雀东南飞并序》', '千万不要因为回去就白白送死，贵贱的分别为什么这样轻易呢？', 0, 0),
(1542, 2, '为', 'wèi', '<介>为了', '<b>为</b>宫室之美，妻妾之奉，所识穷乏者得我与？', '九年级下册｜《鱼我所欲也》', '是为了住宅的华美、妻妾的侍奉和我所认识的穷困人的感激吗？', 0, 0),
(1545, 2, '为', 'wéi', '<动>做；干', '<b>为</b>之奈何？', '高中必修下册｜《鸿门宴》', '这件事怎么办呢？', 0, 0),
(1553, 2, '焉', 'yān', '<代>表示疑问，相当于“何”，可译作“怎么”、“哪里”', '且<b>焉</b>置土石？', '高中必修上册｜《愚公移山》', '况且把土石放在哪里呢？', 0, 0),
(1555, 2, '焉', 'yān', '<代>表示疑问，相当于“何”，可译作“怎么”、“哪里”', '<b>焉</b>有仁人在位，罔民而可为也？', '高中必修下册｜《齐桓晋文之事》', '哪里有仁德的人在位，却可以做欺骗百姓的事呢？', 0, 0),
(1556, 2, '焉', 'yān', '<代>相当于“之”，可译作“它”、“他”等', '犹且从师而问<b>焉</b>。', '高中必修上册｜《师说》', '还跟从老师请教他。', 0, 0),
(1562, 2, '焉', 'yān', '<助>用于句中，表示语气舒缓、停顿', '句读之不知，惑之不解，或师<b>焉</b>，或否<b>焉</b>，小学而大遗', '高中必修上册｜《师说》', '有的从师学习，有的不从师学习，小的方面学习，大的方面却丢弃了。', 0, 0),
(1565, 2, '焉', 'yān', '词缀，用于形容词之后，相当于“……的样子”；在动词前可译作“……地”', '于乱石间择其一二扣之，硿硿<b>焉</b>', '高中选择性必修下册｜《石钟山记》', '在乱石中选择一两处敲击，发出硿硿的声音。', 0, 0),
(1566, 2, '也', 'yě', '<语助>用于句末；表判断', '城北徐公，齐国之美丽者<b>也</b>', '九年级下册｜《邹忌讽齐王纳谏》', '城北的徐公，是齐国最美丽的人。', 0, 0),
(1567, 2, '也', 'yě', '<语助>用于句末；表判断', '张良曰：“沛公之参乘樊哙者<b>也</b>”', '高中必修下册｜《鸿门宴》', '张良说：“刘邦的参乘樊哙，是这样的人。”', 0, 0),
(1568, 2, '也', 'yě', '<语助>用于句末；表示陈述或解释', '即不忍其觳觫，若无罪而就死地，故以羊易之<b>也</b>。', '高中必修下册｜《齐桓晋文之事》', '就是不忍心看它恐惧战栗，像无罪却走向死地，所以用羊替换了它。', 0, 0),
(1569, 2, '也', 'yě', '<语助>用于句末；表示陈述或解释', '雷霆乍惊，宫车过<b>也</b>。', '高中必修下册｜《阿房宫赋》', '像雷霆突然震响一样，是宫车经过了。', 0, 0),
(1570, 2, '也', 'yě', '<语助>用于句末；表感叹', '鸣呼！灭六国者六国<b>也</b>，非秦<b>也</b>。族秦者秦<b>也</b>，非天下<b>也</b>。', '高中选择性必修中册｜《过秦论》', '灭掉六国的是六国自己，不是秦国；使秦国灭族的是秦国自己，不是天下人。', 0, 0),
(1571, 2, '也', 'yě', '<语助>用于句末；表感叹', '至于誓天断发，泣下沾襟，何其衰<b>也</b>!', '高中选择性必修中册｜《五代伶官传序》', '等到对天发誓、割断头发，眼泪流下沾湿衣襟，怎么衰败到这种地步啊！', 0, 0),
(1573, 2, '也', 'yě', '<语助>用于句末；表疑问或反问', '使秦复爱六国之人，则递三世可至万世而为君，谁得而族灭<b>也</b>？', '高中必修下册｜《阿房宫赋》', '假使秦国又爱护六国的百姓，那么传到三世乃至万世做君王，谁能够灭掉它呢？', 0, 0),
(1576, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '是说<b>也</b>，人常疑之。', '高中选择性必修下册｜《石钟山记》', '这是关于石钟山的说法，人们常常怀疑它。', 0, 0),
(1577, 2, '也', 'yě', '<助>语气助词，用于句中；表判断、陈述、解释或语气停顿', '其闻道<b>也</b>亦先乎吾。', '高中必修上册｜《师说》', '他懂得道理也比我早。', 0, 0),
(1578, 2, '也', 'yě', '<语助>用于句末；表感叹', '诗云：“他人有心，予忖度之。”——夫子之谓<b>也</b>。', '高中必修下册｜《齐桓晋文之事》', '《诗经》说：“别人有心思，我可以揣测他。”说的就是先生您这样的人。', 0, 0),
(1580, 2, '也', 'yě', '<语助>用于句末；表疑问或反问', '岂独伶人<b>也</b>哉！', '高中选择性必修中册｜《五代伶官传序》', '难道只是伶人才这样吗？', 0, 0),
(1581, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '愿<b>以</b>十五城请易璧。', '高中常考虚词｜《廉颇蔺相如列传》', '希望用十五座城请求交换和氏璧。', 0, 0),
(1582, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '士大夫终不肯<b>以</b>小舟夜泊绝壁之下。', '高中选择性必修下册｜《石钟山记》', '士大夫最终也不肯用小船在夜里停泊在陡峭的山壁下面。', 0, 0),
(1584, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '久之，能<b>以</b>足音辨人。', '高中选择性必修下册｜《项脊轩志》', '时间久了，能够凭脚步声辨认人。', 0, 0),
(1585, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '皆好辞而<b>以</b>赋见称。', '高中选择性必修中册｜《屈原列传》', '都爱好文辞，并且凭借辞赋受到称赞。', 0, 0),
(1590, 2, '以', 'yǐ', '<介>表示动作行为产生的原因，可译为“因为”、“由于”等', '怀王<b>以</b>不知忠臣之分，故内惑于郑袖，外欺于张仪。', '高中选择性必修中册｜《屈原列传》', '怀王因为不知道忠臣的职分，所以在内被郑袖迷惑，在外被张仪欺骗。', 0, 0),
(1597, 2, '以', 'yǐ', '<连>表示并列或递进关系，可译为“而”、“又”、“并且”等，也可省去', '忽魂悸<b>以</b>魄动。', '高中常考虚词｜《梦游天姥吟留别》', '忽然间魂惊魄动。', 0, 0),
(1598, 2, '以', 'yǐ', '<连>表示承接关系，“以”前的动作行为，往往是后一动作行为的手段和方式，可译为“而”，也可省去', '余与四人拥火<b>以</b>入。', '高中选择性必修下册｜《石钟山记》', '我和四个人举着火把进去。', 0, 0),
(1599, 2, '以', 'yǐ', '<连>表示承接关系，“以”前的动作行为，往往是后一动作行为的手段和方式，可译为“而”，也可省去', '樊哙侧其盾<b>以</b>撞。', '高中必修下册｜《鸿门宴》', '樊哙侧过他的盾牌来撞击。', 0, 0),
(1601, 2, '以', 'yǐ', '<连>表结果，以致、因而', '为秦人积威之所劫，日削月割，<b>以</b>趋于亡', '高中必修下册｜《六国论》', '被秦国积久的威势所胁迫，天天削减、月月割让，以至于走向灭亡。', 0, 0),
(1604, 2, '以', 'yǐ', '<助>和 “来” 组成 “以来”，放在时间词后，表示从过去某时直到现在', '受命<b>以</b>来，夙夜忧叹。', '九年级下册｜《出师表》', '接受遗命以来，早晚忧虑叹息。', 0, 0),
(1607, 2, '以', 'yǐ', '<连>表结果，以致、因而', '逆<b>以</b>煎我怀。', '高中选择性必修下册｜《孔雀东南飞并序》', '反而因此使我的心情受到煎熬。', 0, 0),
(1609, 2, '以', 'yǐ', '<动>认为', '皆<b>以</b>美于徐公。', '高中常考虚词｜《邹忌讽齐王纳谏》', '都认为比徐公美。', 0, 0),
(1612, 2, '以', 'yǐ', '<副>通“已”。已经', '固<b>以</b>怪之矣。', '九年级下册｜《陈涉世家》', '本来已经因此对它感到奇怪了。', 0, 0),
(1614, 2, '以', 'yǐ', '<动>通“已”。停止', '无<b>以</b>，则王乎？', '高中必修下册｜《齐桓晋文之事》', '如果不能不说的话，那就说说王道吧。', 0, 0),
(1617, 2, '以', 'yǐ', '<介>起提宾作用，可译为“把”', '南取百越之地，<b>以</b>为桂林、象郡。', '高中常考虚词｜《常考虚词例句》', '向南夺取百越的土地，把它设置为桂林郡和象郡。', 0, 0),
(1618, 2, '以', 'yǐ', '<介>起提宾作用，可译为“把”', '铸<b>以</b>为金人十二。', '选择性必修中册｜《过秦论》', '铸造它来制作十二个金人。', 0, 0),
(1619, 2, '以', 'yǐ', '<连>表示因果关系，常用在表原因的分句前，可译为“因为”、“由于”', '余是<b>以</b>记之，盖叹郦元之简，而笑李渤之陋也。', '高中选择性必修下册｜《石钟山记》', '我因此记下这件事，是感叹郦道元的简略，也嘲笑李渤的浅陋。', 0, 0),
(1621, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '项王未有<b>以</b>应，曰：“坐。”', '高中必修下册｜《鸿门宴》', '项王没有办法回答，说：“坐下。”', 0, 0),
(1623, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '故不积跬步，无<b>以</b>至千里；不积小流，无<b>以</b>成江', '高中必修上册｜《劝学》', '所以不积累半步，就没有办法到达千里；不汇聚细小水流，就没有办法形成江海。', 0, 0),
(1624, 2, '以', 'yǐ', '<介>表示动作行为所用或所凭借的工具、方法，可视情况译为“拿”、“用”、“凭”、“把”等', '臣无祖母，无<b>以</b>至今日，祖母无臣，无<b>以</b>终余年', '高中选择性必修下册｜《陈情表》', '我没有祖母，就没有办法活到今天；祖母没有我，就没有办法终了她的余年。', 0, 0),
(1625, 2, '因', 'yīn', '<介>介绍动作行为的对象，可译为“依照”、“根据”', '罔不<b>因</b>势象形。', '高中常考虚词｜《核舟记》', '没有不依据地势的形状来刻画的，各自具有各自的情态。', 0, 0),
(1627, 2, '因', 'yīn', '<介>介绍动作行为的依据，可译为“依靠”、“凭借”', '<b>因</b>利乘便，宰割天下，分裂山河', '高中选择性必修中册｜《过秦论》', '凭借有利的形势，割取天下，分割山河。', 0, 0),
(1628, 2, '因', 'yīn', '<介>介绍动作行为的依据，可译为“依靠”、“凭借”', '<b>因</b>人之力而敝之，不仁。', '高中必修下册｜《烛之武退秦师》', '依靠别人的力量却反过来损害他，这是不仁义的。', 0, 0),
(1629, 2, '因', 'yīn', '<介>介绍动作行为的依据，可译为“依靠”、“凭借”', '又<b>因</b>厚币用事者臣靳尚。', '高中选择性必修中册｜《屈原列传》', '（张仪）到了楚国，又凭借丰厚的礼物（贿赂）当权的大臣靳尚。', 0, 0),
(1631, 2, '因', 'yīn', '<介>介绍动作行为发生的条件，可译为“趁机”、“趁着”', '<b>因</b>击沛公于坐。', '高中必修下册｜《鸿门宴》', '趁机在座位上袭击刘邦。', 0, 0),
(1634, 2, '因', 'yīn', '<介>介绍动作行为发生的原因，可译为“因为”、“由于”', '恩所加则思无<b>因</b>喜以谬赏。', '高中必修下册｜《谏太宗十思书》', '对于恩惠所施加的人，就要想到不要因一时高兴而错误地奖赏。', 0, 0),
(1637, 2, '因', 'yīn', '<名>原因；机会', '于今无会<b>因</b>。', '高中常考虚词｜《孔雀东南飞》', '到现在还没有相会的机会。', 0, 0),
(1639, 2, '因', 'yīn', '<动>因袭；遵循', '蒙故业，<b>因</b>遗策。', '高中选择性必修中册｜《过秦论》', '承接已有的基业，沿袭前代的策略。', 0, 0),
(1640, 2, '因', 'yīn', '<动>接续', '加之以师旅，<b>因</b>之以饥馑。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '加上有军队来攻打，接着又有饥荒。', 0, 0),
(1649, 2, '于', 'yú', '<介>介绍动作行为涉及的对象，可译为“对”、“向”等', '爱其子，择师而教之，<b>于</b>其身也，则耻师焉。', '高中必修上册｜《师说》', '爱自己的孩子，选择老师来教他；对于他自己，却以从师学习为可耻。', 0, 0),
(1651, 2, '于', 'yú', '<介>介绍动作行为的主动者，可译为“被”', '故内惑<b>于</b>郑袖，外欺<b>于</b>张仪。', '高中选择性必修中册｜《屈原列传》', '所以在内被郑袖迷惑，在外被张仪欺骗。', 0, 0),
(1655, 2, '于', 'yú', '<介>介绍比较的对象，可译为“比”', '青，取之于蓝，而青<b>于</b>蓝。', '高中必修上册｜《劝学》', '靛青从蓼蓝中取得，却比蓼蓝颜色更深。', 0, 0),
(1666, 2, '与', 'yǔ', '<介>介绍动作行为所涉及的对方，相当于“跟”、“同”等', '沛公军霸上，未得<b>与</b>项羽相见', '高中必修下册｜《鸿门宴》', '刘邦的军队驻扎在霸上，还没有能够和项羽相见。', 0, 0),
(1667, 2, '与', 'yǔ', '<介>介绍动作行为所涉及的对方，相当于“跟”、“同”等', '而翁归，自<b>与</b>汝复算耳', '高中必修下册｜《促织》', '你的父亲回来，自然会再来和你算账。', 0, 0),
(1668, 2, '与', 'yǔ', '<介>介绍动作行为所涉及的对方，相当于“跟”、“同”等', '陈涉少时，尝<b>与</b>人佣耕。', '高中常考虚词｜《陈涉世家》', '陈涉年轻时，曾经和别人一起被雇佣耕田。', 0, 0),
(1670, 2, '与', 'yǔ', '<介>介绍比较对象，相当于“跟……相比”', '吾孰<b>与</b>徐公美？', '高中常考虚词｜《邹忌讽齐王纳谏》', '我和徐公相比，谁更美？', 0, 0),
(1671, 2, '与', 'yǔ', '<介>介绍比较对象，相当于“跟……相比”', '较秦之所得，<b>与</b>战胜而得者，其实百倍。', '高中必修下册｜《六国论》', '把秦国受贿赂所得的土地，同战胜别国所得的土地比较，实际上多一百倍。', 0, 0),
(1675, 2, '与', 'yǔ', '<动>给予', '则<b>与</b>一生彘肩。', '高中必修下册｜《鸿门宴》', '就给他一只完整的猪腿。', 0, 0),
(1676, 2, '与', 'yǔ', '<动>给予', '<b>与</b>尔三矢，尔其无忘乃父之志。', '高中常考虚词｜《五代史伶官传序》', '给你三支箭，你一定不要忘记你父亲的遗志。', 0, 0),
(1677, 2, '与', 'yǔ', '<动>结交；交好', '因人之力而敝之，不仁；失其所<b>与</b>，不知。', '高中必修下册｜《烛之武退秦师》', '依靠别人的力量却反过来损害他，这是不仁义的；失去自己的同盟，不明智。', 0, 0),
(1678, 2, '与', 'yǔ', '<动>结交；交好', '合从缔交，相<b>与</b>为一', '高中选择性必修中册｜《过秦论》', '联合各国缔结盟约，彼此结为一体。', 0, 0),
(1679, 2, '与', 'yǔ', '<动>结交；交好', '<b>与</b>嬴而不助五国也', '高中必修下册｜《六国论》', '齐国亲附秦国，却不帮助其他五国。', 0, 0),
(1682, 2, '与', 'yǔ', '<动>赞同，赞许', '吾<b>与</b>点也。', '高中常考虚词｜《子路、曾晳、冉有、公西华侍坐》', '我赞同曾点。', 0, 0),
(1686, 2, '与', 'yǔ', '<通假>通“欤“，语气助词，表示疑问、反诘或感叹，相当于“吗”、“吧”、“啊”', '然则废衅钟<b>与</b>？', '高中必修下册｜《齐桓晋文之事》', '那么废除衅钟的仪式吗？', 0, 0),
(1687, 2, '与', 'yǔ', '<介>介绍比较对象，相当于“跟……相比”', '谓其妻曰：“我孰<b>与</b>城北徐公美？”', '高中常考虚词｜《邹忌讽齐王纳谏》', '他对妻子说：“我和城北徐公相比，谁更美？”', 0, 0),
(1688, 2, '与', 'yǔ', '<介>介绍比较对象，相当于“跟……相比”', '沛公曰：“孰<b>与</b>君少长？”', '高中必修下册｜《鸿门宴》', '刘邦说：“你和项伯相比，谁年长谁年幼？”', 0, 0),
(1693, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '<b>则</b>与斗卮酒。', '高中必修下册｜《鸿门宴》', '于是给他一大杯酒。', 0, 0),
(1694, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '故木受绳<b>则</b>直，金就砺<b>则</b>利。', '高中必修上册｜《劝学》', '所以木材用墨线量过就直，刀剑靠近磨刀石就锋利。', 0, 0),
(1695, 2, '则', 'zé', '<连>表示假设，相当于“如果”、“假使”', '入<b>则</b>无法家拂士，出<b>则</b>无敌国外患者，国恒亡。', '高中常考虚词｜《生于忧患，死于安乐》', '进入国内如果没有守法的大臣，离开国内如果没有敌国外患，国家常常会灭亡。', 0, 0),
(1697, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '位卑<b>则</b>足羞，官盛<b>则</b>近谀。', '高中必修上册｜《师说》', '职位低就觉得羞耻，官职高就近于谄媚。', 0, 0),
(1700, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '手裁举，<b>则</b>双超忽而跃', '高中必修下册｜《促织》', '手刚抬起，两只蟋蟀就迅速跳开了。', 0, 0),
(1709, 2, '则', 'zé', '<连>表示顺承，相当于“就”、“便”', '居<b>则</b>曰：“不吾知也！”', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '平日在家就说：“没有人了解我！”', 0, 0),
(1715, 2, '者', 'zhě', '<代>用在数词后面，往往总指上文所提到的人、事、物。翻译时在人、事、物名称前加“个”、“件”、“种”等', '或异二<b>者</b>之为，何哉？', '九年级下册｜《岳阳楼记》', '有人不同于这两种人的心情，为什么呢？', 0, 0),
(1721, 2, '者', 'zhě', '<助>用在句中主语的后面，表示停顿、判断，无实义', '师<b>者</b>，所以传道受业解惑也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 0, 0),
(1726, 2, '者', 'zhě', '<助>用在因果复句或条件复句偏句的末尾，提示原因或条件', '吾妻之美我<b>者</b>，私我也。', '九年级下册｜《邹忌讽齐王纳谏》', '我的妻子认为我美，是因为偏爱我。', 0, 0),
(1728, 2, '者', 'zhě', '<助>用在疑问句全句末，表示疑问语气，相当于“呢”', '谁为大王为此计<b>者</b>？', '高中必修下册｜《鸿门宴》', '是谁替大王出了这个计策？', 0, 0),
(1732, 2, '之', 'zhī', '<代>指示代词，相当于“这个”、“这”、“这种”等', '然语<b>之</b>，又恐汝日日为吾担忧。', '高中常考虚词｜《与妻书》', '这样告诉你，又怕你每天替我担忧。', 0, 0),
(1739, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '臣<b>之</b>壮也，犹不如人；今老矣，无能为也已。', '高中必修下册｜《烛之武退秦师》', '我年轻时尚且不如别人，现在年老了，更没有能力了。', 0, 0),
(1740, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '客<b>之</b>美我者，欲有求于我也。', '高中常考虚词｜《邹忌讽齐王纳谏》', '客人认为我美，是因为想要向我有所求。', 0, 0),
(1743, 2, '之', 'zhī', '<助>用宾语前置的标志', '句读<b>之</b>不知，惑<b>之</b>不解，或师焉，或不焉。', '高中必修上册｜《师说》', '不懂得断句，不能解决疑惑，有的从师学习，有的不从师学习。', 0, 0),
(1745, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '诗云：“他人有心，予忖度<b>之</b>。”', '高中必修下册｜《齐桓晋文之事》', '《诗经》说：“别人有心思，我可以揣测他。”', 0, 0),
(1746, 2, '之', 'zhī', '<助>定语后置的标志', '蚓无爪牙<b>之</b>利，筋骨<b>之</b>强。', '高中必修上册｜《劝学》', '蚯蚓没有锋利的爪牙和强健的筋骨。', 0, 0),
(1747, 2, '之', 'zhī', '<助>定语后置的标志', '人又谁能以身<b>之</b>察察，受物<b>之</b>汶汶者乎', '高中选择性必修中册｜《屈原列传》', '世上又有谁能让洁白的身体蒙受污浊，受到外物玷污呢？', 0, 0),
(1749, 2, '之', 'zhī', '<助>用在表示时间的副词后，补足音节，没有实义', '余扃牖而居，久<b>之</b>，能以足音辨人。', '高中选择性必修下册｜《项脊轩志》', '我关着窗子独自居住，时间久了，能够凭脚步声辨认人。', 0, 0),
(1751, 2, '之', 'zhī', '<动>到……去', '胡为乎遑遑欲何<b>之</b>？', '高中常考虚词｜《归去来兮辞》', '为什么还要心神不定地想去哪里呢？', 0, 0),
(1753, 2, '之', 'zhī', '<动>到……去', '曰：“牛何<b>之</b>？”', '高中必修下册｜《齐桓晋文之事》', '问道：“牛要到哪里去？”', 0, 0),
(1754, 1, '方', 'fāng', '<副>正，正在', '<b>方</b>其破荆州，下江陵，顺流而东也。', '高中必修上册｜《赤壁赋》', '正当他攻破荆州、占领江陵、顺流向东进军的时候。', 1, 0),
(1755, 1, '方', 'fāng', '<副>正，正在', '<b>方</b>欲行，转视积薪后，一狼洞其中，意将隧入以攻其后也。', '七年级上册｜《狼》', '屠户正要走，转身看柴草堆的后面，发现一只狼正在打洞，想要从通道进入来攻击他的后面。', 1, 0),
(1756, 1, '冠', 'guàn', '<名>古代男子二十岁束发加冠的礼仪，表示已成人', '今臣以弱<b>冠</b>，非臣陨首所能上报。', '高中选择性必修下册｜《陈情表》', '如今我已到弱冠之年，所受的恩遇不是杀身捐躯所能报答的。', 1, 0),
(1757, 1, '让', 'ràng', '<动>谦让；礼让', '当仁不<b>让</b>于师。', '高中选择性必修上册｜《论语》十二章', '面对仁义，即使对老师也不谦让。', 1, 0),
(1759, 1, '得', 'dé', '<动>获得；得到；取得。与“失”相对', '今日割五城，明日割十城，然后<b>得</b>一夕安寝。', '高中选择性必修中册｜《六国论》', '今天割让五座城，明天割让十座城，然后才能得到一夜的安睡。', 1, 0),
(1760, 1, '得', 'dé', '<动>获得；得到；取得。与“失”相对', '昭王<b>得</b>范雎，废穰侯，逐华阳，强公室，杜私门。', '高中必修下册｜《谏逐客书》', '秦昭王得到范雎，废除穰侯，驱逐华阳君，使王室强大，杜绝权贵私门。', 1, 0),
(1761, 1, '保', 'bǎo', '<动>安抚，安定', '愿陛下矜悯愚诚，听臣微志，庶刘侥幸，<b>保</b>卒余年。', '高中选择性必修下册｜《陈情表》', '希望陛下怜悯我的诚心，听任我微小的愿望，使祖母能够侥幸保全余年。', 1, 0),
(1762, 1, '保', 'bǎo', '<动>安抚，安定', '永<b>保</b>无疆之休。', '高中必修下册｜《谏太宗十思疏》', '永远保持无边的美好。', 1, 0),
(1765, 1, '举', 'jǔ', '<动>推及', '<b>举</b>以予人，如弃草芥。', '高中选择性必修中册｜《过秦论》', '拿来送给别人，就像丢弃小草一样。', 1, 0),
(1768, 1, '度', 'duó', '<动>衡量', '试使山东之国与陈涉<b>度</b>长絜大，比权量力，则不可同年而语矣。', '高中选择性必修中册｜《过秦论》', '假使把崤山以东的国家同陈涉量一量长短、比一比大小，比较一下权势和力量，那就不能相提并论了。', 1, 0),
(1769, 1, '治', 'zhì', '<动>治理', '孤岂欲卿<b>治</b>经为博士邪！', '高中必修下册｜《孙权劝学》', '我难道想要你研究儒家经典成为学官吗？', 1, 0),
(1770, 1, '爱', 'ài', '<动>吝惜', '秦<b>爱</b>纷奢，人亦念其家。', '高中必修下册｜《阿房宫赋》', '秦人喜爱奢侈，百姓也顾念自己的家。', 1, 0),
(1771, 1, '安', 'ān', '<形>安定；安稳；安宁；安全', '然后得一夕<b>安</b>寝。', '高中选择性必修中册｜《六国论》', '这样之后才能得到一夜安稳的睡眠。', 1, 0),
(1773, 1, '诚', 'chéng', '<副>果真', '<b>诚</b>能见可欲则思知足以自戒。', '高中必修下册｜《谏太宗十思疏》', '果真见到想得到的东西，就想到知足来自我警戒。', 1, 0),
(1775, 1, '解', 'jiě', '<动>分解，剖开', '始臣之<b>解</b>牛之时，所见无非牛者。', '高中必修下册｜《庖丁解牛》', '开始我宰牛的时候，眼中所看到的没有不是整头牛的。', 1, 0),
(1776, 1, '解', 'jiě', '<动>分解，剖开', '动刀甚微，謋然已<b>解</b>，如土委地。', '高中必修下册｜《庖丁解牛》', '刀刃轻轻一动，牛体就分解开来，像泥土散落在地上一样。', 1, 0),
(1777, 1, '中', 'zhòng', '<动>合乎', '木直<b>中</b>绳，輮以为轮，其曲中规。', '高中必修上册｜《劝学》', '木材直得合乎墨线，用火烤使它弯曲制成车轮，弯曲程度合乎圆规。', 1, 0),
(1778, 1, '中', 'zhòng', '<动>合乎', '其曲<b>中</b>规。', '高中必修上册｜《劝学》', '它弯曲的程度合乎圆规。', 1, 0),
(1779, 1, '族', 'zú', '<名>筋骨交错的地方', '虽然，每至于<b>族</b>，吾见其难为，怵然为戒。', '高中必修下册｜《庖丁解牛》', '即使这样，每当遇到筋骨交错聚结的地方，我看见它难以处理，就警惕起来。', 1, 0),
(1780, 1, '发', 'fā', '<动>出，发出声音', '见其<b>发</b>矢十中八九，但微颔之。', '七年级下册｜《卖油翁》', '看见他射箭十支能射中八九支，只是微微点头。', 1, 0),
(1781, 1, '发', 'fā', '<动>出，发出声音', '忽闻水上琵琶声，主人忘归客不<b>发</b>。', '高中必修上册｜《琵琶行并序》', '忽然听到江面传来的琵琶声，主人忘了回去，客人也不再出发。', 1, 0),
(1782, 1, '养', 'yǎng', '<动>保养', '俭以<b>养</b>德。', '七年级上册｜《诫子书》', '用节俭来培养品德。', 1, 0),
(1783, 1, '养', 'yǎng', '<动>保养', '可以尽豫游之乐，可以<b>养</b>松乔之寿。', '高中必修下册｜《谏太宗十思疏》', '可以尽情享受游乐，可以获得像赤松子、王子乔那样的长寿。', 1, 0),
(1784, 1, '技', 'jì', '<名>技艺', '臣之所好者道也，进乎<b>技</b>矣。', '高中必修下册｜《庖丁解牛》', '我所喜爱的是自然的规律，已经超过一般的技艺了。', 1, 0),
(1785, 1, '技', 'jì', '<名>技艺', '<b>技</b>经肯綮之未尝，而况大軱乎！', '高中必修下册｜《庖丁解牛》', '技艺施展从未碰到筋骨经络，更何况大骨呢！', 1, 0),
(1786, 1, '经', 'jīng', '<名>经脉', '依乎天理，批大郤，导大窾，因其固然，技<b>经</b>肯綮之未尝。', '高中必修下册｜《庖丁解牛》', '依照牛体天然的结构，击入大的缝隙，引导刀进入大的空隙，顺着牛体本来的结构，连筋骨经络都没有碰到。', 1, 0),
(1787, 1, '经', 'jīng', '<名>经脉', '技<b>经</b>肯綮之未尝，而况大軱乎！', '高中必修下册｜《庖丁解牛》', '技艺施展从未碰到筋骨经络，更何况大骨呢！', 1, 0),
(1788, 1, '得', 'dé', '<动>能够', '安能摧眉折腰事权贵，使我不<b>得</b>开心颜！', '高中必修上册｜《梦游天姥吟留别》', '怎么能低头弯腰侍奉权贵，使我不能舒展笑颜！', 1, 0),
(1789, 1, '得', 'dé', '<动>能够', '久在樊笼里，复<b>得</b>返自然。', '高中必修上册｜《归园田居（其一）》', '长久地困在樊笼里，如今终于能够回归自然。', 1, 0),
(1792, 1, '安', 'ān', '<形>使……安定/安宁', '将有作，则思知止以<b>安</b>人。', '高中必修下册｜《谏太宗十思疏》', '将要兴建宫室，就要想到适可而止，使百姓安宁。', 1, 0),
(1795, 1, '度', 'duó', '<动>考虑', '不为侵官，故不<b>度</b>义而后动。', '高中必修下册｜《答司马谏议书》', '不是侵夺官职，所以不必考虑是否合乎道义才行动。', 1, 0),
(1796, 1, '度', 'duó', '<动>考虑', '盘庚不为怨者故改其<b>度</b>。', '高中必修下册｜《答司马谏议书》', '盘庚不因为有人怨恨的缘故就改变他的计划。', 1, 0),
(1797, 1, '得', 'dé', '<形>合适；恰当', '此言<b>得</b>之。', '高中选择性必修中册｜《六国论》', '这话说得很正确。', 1, 0),
(1798, 1, '得', 'dé', '<动>获得；得到；取得。与“失”相对', '<b>得</b>道者多助，失道者寡助。', '八年级上册｜《得道多助，失道寡助》', '施行仁政的君主会得到更多帮助，不施行仁政的君主得到的帮助就少。', 1, 0),
(1800, 1, '举', 'jǔ', '<动>被选拔', '前太守臣逵察臣孝廉，后刺史臣荣<b>举</b>臣秀才。', '高中选择性必修下册｜《陈情表》', '先前太守臣逵察举我为孝廉，后来刺史臣荣举荐我为秀才。', 1, 0),
(1801, 1, '方', 'fāng', '<名>方圆，纵横', '<b>方</b>六七十，如五六十，求也为之，比及三年，可使足民。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '纵横六七十里或五六十里的小国，如果让我治理，三年可以使百姓富足。', 1, 0),
(1802, 1, '方', 'fāng', '<名>方圆，纵横', '今齐地<b>方</b>千里，百二十城。', '九年级上册｜《邹忌讽齐王纳谏》', '如今齐国土地方圆一千里，有一百二十座城池。', 1, 0),
(1803, 1, '诚', 'chéng', '<副>确实，的确', '战败而亡，<b>诚</b>不得已。', '高中选择性必修中册｜《六国论》', '战败而灭亡，确实是不得已的事情。', 1, 0),
(1805, 1, '举', 'jǔ', '<动>举起，提出', '驾一叶之扁舟，<b>举</b>匏尊以相属。', '高中必修上册｜《赤壁赋》', '驾着一叶小船，举起葫芦做的酒器互相劝饮。', 1, 0),
(1806, 1, '举', 'jǔ', '<动>举起，提出', '<b>举</b>先王之政，以兴利除弊。', '高中必修下册｜《答司马谏议书》', '推行先王的政令，来兴办有利的事业、革除弊端。', 1, 0),
(1807, 1, '爱', 'ài', '<动>爱护，吝惜', '使六国各<b>爱</b>其人，则足以拒秦。', '高中必修下册｜《阿房宫赋》', '假使六国各自爱护百姓，就足以抵抗秦国。', 1, 0),
(1808, 1, '爱', 'ài', '<动>爱护，吝惜', '向使三国各<b>爱</b>其地，齐人勿附于秦。', '高中选择性必修中册｜《过秦论》', '假使韩、魏、楚三国各自爱惜自己的土地，齐国不亲附秦国。', 1, 0),
(1809, 1, '举', 'jǔ', '<动>攻取，占领', '获楚、魏之师，<b>举</b>地千里，至今治强。', '高中必修下册｜《谏逐客书》', '打败楚魏军队，攻取千里土地，直到如今政治安定、国力强大。', 1, 0),
(1810, 1, '举', 'jǔ', '<副>全，所有', '<b>举</b>世混浊而我独清，众人皆醉而我独醒。', '高中选择性必修中册｜《屈原列传》', '世上所有人都混浊，只有我清白；众人都醉了，只有我清醒。', 1, 0),
(1811, 1, '故', 'gù', '<连>所以，因此', '<b>故</b>不积跬步，无以至千里。', '高中必修上册｜《劝学》', '所以不积累每一步，就没有办法到达千里之外。', 1, 0),
(1812, 1, '爱', 'ài', '<动>吝惜', '不<b>爱</b>珍器重宝肥饶之地，以致天下之士。', '高中选择性必修中册｜《过秦论》', '不吝惜珍贵器物、重宝和肥沃富饶的土地，来招致天下的士人。', 1, 0),
(1824, 1, '举', 'jǔ', '<动>攻取，占领', '西<b>举</b>巴蜀。', '高中选择性必修中册｜《过秦论》', '向西攻取巴蜀。', 1, 0),
(1826, 1, '故', 'gù', '<连>所以，因此', '<b>故</b>木受绳则直，金就砺则利。', '高中必修上册｜《劝学》', '所以木材用墨线量过就直，刀剑等金属靠近磨刀石就锋利。', 1, 0),
(1827, 2, '安', 'ān', '<疑问副词>怎么；哪里', '<b>安</b>见方六七十如五六十而非邦也者？', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '怎么见得方圆六七十里或者五六十里的地方就不是国家呢？', 1, 0),
(1828, 2, '安', 'ān', '<疑问副词>怎么；哪里', '<b>安</b>能摧眉折腰事权贵，使我不得开心颜！', '高中必修上册｜《梦游天姥吟留别》', '怎么能低头弯腰侍奉权贵，使我不能舒展笑颜！', 1, 0),
(1829, 1, '方', 'fāng', '<名>方形，与“圆”相对', '形若土狗，梅花翅，<b>方</b>首，长颈。', '高中必修下册｜《促织》', '（它）形状像土狗，有梅花翅，方头，长脖子。', 1, 0),
(1830, 1, '方', 'fāng', '<形>正直', '<b>方</b>正之不容也。', '高中选择性必修中册｜《屈原列传》', '正直的人不被容纳。', 1, 0),
(1831, 1, '方', 'fāng', '<名>方向；方位', '不知东<b>方</b>之既白。', '高中必修上册｜《赤壁赋》', '不知不觉东方已经发白。', 1, 0),
(1832, 1, '方', 'fāng', '<名>区域；地方', '有朋自远<b>方</b>来，不亦乐乎。', '七年级上册｜《论语十二章》', '有志同道合的人从远方来，不也是很快乐吗？', 1, 0),
(1833, 1, '方', 'fāng', '<名>方圆；周围', '<b>方</b>宅十余亩，草屋八九间。', '高中必修上册｜《归园田居（其一）》', '住宅四周有十多亩地，草屋有八九间。', 1, 0),
(1834, 1, '方', 'fāng', '<介>当；在', '故<b>方</b>其盛也，举天下之豪杰。', '高中选择性必修中册｜《五代史伶官传序》', '所以当他强盛时，全天下的豪杰，没有人能和他抗争。', 1, 0),
(1835, 1, '冠', 'guān', '<名>帽子', '新沐者必弹<b>冠</b>。', '高中选择性必修中册｜《屈原列传》', '刚洗过头的人要弹去帽子上的尘土。', 1, 0),
(1836, 1, '冠', 'guān', '<名>鸟类头顶上突出的肉或翎毛', '旋见鸡伸颈摆扑，临视，则虫集<b>冠</b>上，力叮不释。', '高中必修下册｜《促织》', '不一会儿，只见鸡伸长脖子扑腾，仔细一看，蟋蟀落在鸡冠上，用力叮住不放。', 1, 0),
(1837, 1, '让', 'ràng', '<动>推辞；拒绝', '是以太山不<b>让</b>土壤，故能成其大。', '高中必修下册｜《谏逐客书》', '因此泰山不拒绝土壤，所以能成就它的高大。', 1, 0),
(1838, 1, '得', 'dé', '<形>得意；满足', '当其欣于所遇，暂<b>得</b>于己，快然自足。', '高中选择性必修下册｜《兰亭集序》', '当他们对所接触的事物感到高兴，一时感到自得，感到快乐和满足。', 1, 0),
(1839, 1, '得', 'dé', '<助>表示动作完成或补充说明结果', '十三学<b>得</b>琵琶成，名属教坊第一部。', '高中必修上册｜《琵琶行并序》', '十三岁学会弹琵琶，名字列在教坊第一部。', 1, 0),
(1840, 1, '得', 'dé', '<动>实现；达到', '既<b>得</b>志则纵情以傲物。', '高中必修下册｜《谏太宗十思疏》', '得志以后就放纵情感傲视他人。', 1, 0),
(1841, 1, '安', 'ān', '<形>安适；安逸', '倚南窗以寄傲，审容膝之易<b>安</b>。', '高中选择性必修下册｜《归去来兮辞并序》', '靠着南窗寄托傲世的情怀，深知这狭小的小屋也容易使人安适。', 1, 0),
(1842, 1, '安', 'ān', '<形>安适；安逸', '然后知生于忧患而死于<b>安</b>乐也。', '八年级上册｜《生于忧患，死于安乐》', '这样之后才知道，忧患使人生存发展，安逸享乐使人衰败灭亡。', 1, 0),
(1843, 1, '安', 'ān', '<形>安适；安逸', '予出官二年，恬然自<b>安</b>。', '高中必修上册｜《琵琶行并序》', '我被贬出京城两年，心境安然自得。', 1, 0),
(1844, 2, '而', 'ér', '<连>表修饰', '吾尝终日<b>而</b>思矣。', '高中必修上册｜《劝学》', '我曾经整天地冥思苦想。', 0, 0),
(1846, 2, '而', 'ér', '<连>表并列', '蟹六跪<b>而</b>二螯。', '高中必修上册｜《劝学》', '螃蟹有六条腿，还有两只大钳子。', 0, 0),
(1847, 2, '而', 'ér', '<连>表并列', '则知明<b>而</b>行无过矣。', '高中必修上册｜《劝学》', '那么就智慧明达，行为没有过错了。', 0, 0),
(1848, 2, '而', 'ér', '<连>表并列', '侣鱼虾<b>而</b>友麋鹿。', '高中必修上册｜《赤壁赋》', '以鱼虾为伴，以麋鹿为友。', 0, 0),
(1849, 2, '而', 'ér', '<连>表并列', '泉香<b>而</b>酒洌。', '九年级上册｜《醉翁亭记》', '泉水香甜，酒水清醇。', 0, 0),
(1852, 2, '而', 'ér', '<连>表并列', '然后知生于忧患<b>而</b>死于安乐也。', '八年级上册｜《生于忧患，死于安乐》', '这样就知道，忧患可以使人生存，安逸享乐会使人灭亡。', 0, 0),
(1853, 1, '师', 'shī', '<名>老师', '<b>师</b>者，所以传道受业解惑也。', '高中必修上册｜《师说》', '老师，是依靠他来传授道、教授学业、解除疑惑的人。。', 0, 0),
