(1857, 1, '师', 'shī', '<名>有专门知识或技艺的人', '巫医乐<b>师</b>百工之人，君子不齿。', '高中必修上册｜《师说》', '巫医、乐师和各种工匠这类人，士大夫们看不起。', 0, 0),
(1858, 1, '师', 'shī', '<名>有专门知识或技艺的人', '而渔工水<b>师</b>虽知而不能言。', '高中选择性必修下册｜《石钟山记》', '而渔夫船工虽然知道（原因），却不能用文字表述出来。', 0, 0),
(1859, 1, '师', 'shī', '<动>学习，效法', '巫医乐<b>师</b>百工之人，不耻相<b>师</b>。', '高中必修上册｜《师说》', '他懂得道理，本来就比我早，我跟从他，拜他为老师。', 0, 0),
(1860, 1, '师', 'shī', '<动>学习，效法', '吾<b>师</b>道也，夫庸知其年之先后生于吾乎？', '高中必修上册｜《师说》', '我学习的是道理，哪里管他的年龄比我大还是比我小呢？', 0, 0),
(1861, 1, '师', 'shī', '<意动>以……为师，意动用法', '生乎吾前，其闻道也固先乎吾，吾从而<b>师</b>之。', '高中必修上册｜《师说》', '巫医、乐师和各种工匠这类人，士大夫们看不起。', 0, 0),
(1862, 1, '师', 'shī', '<意动>以……为师，意动用法', '孔子<b>师</b>郯子、苌弘、<b>师</b>襄、老聃。', '高中必修上册｜《师说》', '孔子以郯子、苌弘、师襄、老聃为师。', 0, 0),
(1863, 1, '惑', 'huò', '<名>疑惑，疑难问题', '欲人之无<b>惑</b>也难矣！', '高中必修上册｜《师说》', '想要人们没有疑惑，很难啊！', 0, 0),
(1864, 1, '惑', 'huò', '<名>疑惑，疑难问题', '句读之不知，<b>惑</b>之不解。', '高中必修上册｜《师说》', '不懂得句读，不能解决疑惑。', 0, 0),
(1865, 1, '惑', 'huò', '<动>有了疑惑，遇到疑难', '<b>惑</b>而不从师。', '高中必修上册｜《师说》', '有了疑惑却不跟从老师学习。', 0, 0),
(1866, 1, '惑', 'huò', '<形>糊涂', '于其身也，则耻师焉，<b>惑</b>矣。', '高中必修上册｜《师说》', '可对于他自己，却以从师学习为耻，真是糊涂啊！', 0, 0),
(1867, 1, '从', 'cóng', '<动>跟随，跟从', '古之圣人，其出人也远矣，犹且<b>从</b>师而问焉。', '高中必修上册｜《师说》', '古代的圣人，超出一般人很远，尚且要跟从老师请教。', 0, 0),
(1868, 1, '从', 'cóng', '<动>跟随，跟从', '天下云集响应，赢粮而景<b>从</b>。', '高中选择性必修中册｜《过秦论》', '古代的圣人，超出一般人很远，尚且要跟从老师请教。', 0, 0),
(1869, 1, '从', 'cóng', '<动>跟随，跟从', '择其善者而<b>从</b>之。', '高中选择性必修中册｜《过秦论》', '选取他们好的方面来学习。', 0, 0),
(1870, 1, '从', 'cóng', '<动>跟随，跟从', '小惠未遍，民弗<b>从</b>也。', '九年级下册｜《曹刿论战》', '这种小恩小惠不能遍及百姓，百姓是不会听从您的。', 0, 0),
(1871, 1, '从', 'cóng', '<使动>使…… 跟从，率领', '沛公旦日<b>从</b>百余骑来见项王。', '高中必修下册｜《鸿门宴》', '第二天刘邦带着一百多骑兵来拜见项王。', 0, 0),
