(1878, 1, '益', 'yì', '<名>好处、益处', '必能裨补阙漏，有所广<b>益</b>。', '九年级下册｜《出师表》', '一定能够弥补缺失疏漏，获得更多好处。', 0, 0),
(1879, 1, '穷', 'qióng', '<动>尽，停止', '子子孙孙无<b>穷</b>匮也。', '八年级上册｜《愚公移山》', '子子孙孙没有穷尽。', 0, 0),
(1880, 1, '穷', 'qióng', '<动>尽，停止', '而乐亦无<b>穷</b>也。', '九年级上册｜《醉翁亭记》', '那乐趣也是没有穷尽的。', 0, 0),
(1881, 1, '穷', 'qióng', '<动>走到…… 尽头、穷尽', '复前行，欲<b>穷</b>其林。', '八年级下册｜《桃花源记》', '那乐趣也是没有穷尽的。', 0, 0),
(1882, 1, '穷', 'qióng', '<形>困窘，处境艰难', '人<b>穷</b>则反本。', '高中选择性必修中册｜《屈原列传》', '人处境困窘的时候，就会追念本源。', 0, 0),
(1883, 1, '穷', 'qióng', '<形>困窘，处境艰难', '谗人间之，可谓<b>穷</b>矣。', '高中选择性必修中册｜《屈原列传》', '谗佞小人离间他，（屈原）可以说是处境困窘了。', 0, 0),
(1884, 1, '达', 'dá', '<形>显达，显贵', '苟全性命于乱世，不求闻<b>达</b>于诸侯。', '九年级下册｜《出师表》', '在乱世里苟且保全性命，不奢求在诸侯之中扬名显贵。', 0, 0),
(1885, 1, '达', 'dá', '<形>显达，显贵', '本图宦<b>达</b>，不矜名节。', '高中选择性必修下册｜《陈情表》', '本来就谋求官职显达，并不顾惜名节。', 0, 0),
