(1918, 1, '行', 'xíng', '<动>行走', '三人<b>行</b>，必有我师焉。', '七年级上册｜《〈论语〉十二章》', '几个人同行，在其中一定有人可以做我的老师', 0, 0),
(1919, 1, '行', 'xíng', '<动>行走', '<b>行</b>拂乱其所为。', '八年级上册｜《生于忧患，死于安乐》', '使他做事不顺。', 0, 0),
(1920, 1, '行', 'xíng', '<动>出行', '余自齐安舟<b>行</b>适临汝。', '高中选择性必修下册｜《石钟山记》', '我从齐安坐船前行，到临汝去。', 0, 0),
(1921, 1, '行', 'xíng', '<动>出行', '<b>行</b>李之往来，共其乏困。', '高中必修下册｜《烛之武退秦师》', '出使的人来来往往，（郑国可以）供给他们缺少的物资。', 0, 0),
(1922, 1, '行', 'xíng', '<名>品行，德行', '君子之<b>行</b>，静以修身，俭以养德。', '七年级上册｜《诫子书》', '君子的品行，依靠宁静修养身心，依靠节俭培养品德。', 0, 0),
(1923, 1, '行', 'xíng', '<名>品行，德行', '君子博学而日参省乎己，则知明而<b>行</b>无过矣。', '高中必修上册｜《劝学》', '君子广泛学习并且每天反省自己，就能智慧明达，品行也不会有过失', 0, 0),
(1924, 1, '道', 'dào', '<名>道路', '伐竹取<b>道</b>，下见小潭。', '八年级下册｜《小石潭记》', '砍倒竹子，开辟出一条道路，往下走就看见一个小水潭。', 0, 0),
(1925, 1, '道', 'dào', '<名>道路', '会天大雨，<b>道</b>不通，度已失期。', '九年级下册｜《陈涉世家》', '恰巧遇到天下大雨，道路不通，估计已经误了期限。', 0, 0),
(1926, 1, '道', 'dào', '<名>道路', '呼尔而与之，行<b>道</b>之人弗受。', '九年级下册｜《鱼我所欲也》', '吆喝着给他，过路的行人也不肯接受。', 0, 0),
(1927, 1, '道', 'dào', '<名>方法、途径', '策之不以其<b>道</b>。', '八年级下册｜《马说》', '用马鞭赶它，不按照（驱使千里马的）正确方法。', 0, 0),
(1928, 1, '道', 'dào', '<名>方法、途径', '行军用兵之<b>道</b>，非及向时之士也。', '高中选择性必修中册｜《过秦论》', '行军用兵的策略，比不上先前的那些谋士。', 0, 0),
(1929, 1, '道', 'dào', '<名>方法、途径', '赂秦而力亏，破灭之<b>道</b>也。', '高中必修下册｜《六国论》', '割让土地贿赂秦国，使自身国力亏损，这就是它们走向灭亡的根本原因。', 0, 0),
(1930, 1, '道', 'dào', '<名>道德，道义', '伐无<b>道</b>，诛暴秦。', '九年级下册｜《陈涉世家》', '讨伐没有道义的暴君，诛灭暴虐的秦朝。', 0, 0),
(1931, 1, '道', 'dào', '<名>道理，规律', '师者，所以传<b>道</b>受业解惑也。', '高中必修上册｜《师说》', '老师，是用来传授道理、教授学业、解答疑难问题的人。', 0, 0),
(1932, 1, '道', 'dào', '<名>道理，规律', '闻<b>道</b>有先后，术业有专攻。', '高中必修上册｜《师说》', '领会道理有早有晚，学问技艺各有专门的研究。', 0, 0),
(1933, 1, '道', 'dào', '<名>道理，规律', '臣之所好者<b>道</b>也，进乎技矣。', '高中必修下册｜《庖丁解牛》', '我所追求的是自然的规律，已经超过（一般的）技艺了。', 0, 0),
(1934, 1, '道', 'dào', '<名>学说，主张', '既加冠，益慕圣贤之<b>道</b>。', '高中必修下册｜《送东阳马生序》', '成年以后，更加仰慕古代圣贤的学说。', 0, 0),
(1935, 1, '道', 'dào', '<名>学说，主张', '于是废先王之<b>道</b>，焚百家之言。', '高中选择性必修中册｜《过秦论》', '在这时废弃前代帝王的治国思想，焚烧各学派的著作。', 0, 0),
(1936, 1, '道', 'dào', '<动>说，谈论', '不足为外人<b>道</b>也。', '八年级下册｜《桃花源记》', '（这里的事）不值得对外面的人说啊。', 0, 0),
(1937, 1, '道', 'dào', '<动>说，谈论', '仲尼之徒无<b>道</b>桓文之事者。', '高中必修下册｜《齐桓晋文之事》', '孔子的弟子当中，没有谈论齐桓公、晋文公事迹的人。', 0, 0),
(1938, 1, '率', 'shuài', '<动>率领，带领', '自云先世避秦时乱，<b>率</b>妻子邑人来此绝境。', '八年级下册｜《桃花源记》', '他们自己说祖先为了躲避秦朝战乱，带领妻子儿女和同乡来到这个与世隔绝的地方。', 0, 0),
(1939, 1, '率', 'shuài', '<动>率领，带领', '遂<b>率</b>子孙荷担者三夫，叩石垦壤。', '八年级上册｜《愚公移山》', '于是愚公带领儿孙中能挑担子的三个人，凿石头、挖泥土。', 0, 0),
(1940, 1, '率', 'shuài', '<动>率领，带领', '<b>率</b>疲弊之卒，将数百之众，转而攻秦。', '高中选择性必修中册｜《过秦论》', '率领着疲惫无力的士兵，带领几百人的队伍，掉转头来攻打秦国。', 0, 0),
(1941, 1, '率', 'shuài', '<副>全都、一概‌', '六国互丧，<b>率</b>赂秦耶？', '高中必修下册｜《六国论》', '六国相继灭亡，全都是因为贿赂秦国吗？', 0, 0),
(1942, 1, '率', 'shuài', '<动>遵循，遵从', '此吾所以敢<b>率</b>性就死不顾汝也。', '高中必修下册｜《与妻书》', '这就是我敢于顺着本心赴死、抛下你的原因。', 0, 0),
(1943, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '苟全性命<b>于</b>乱世，不求闻达<b>于</b>诸侯。', '九年级下册｜《出师表》', '在乱世里苟且保全性命，不奢求在诸侯之中扬名显贵。', 0, 0),
(1944, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '安陵君因使唐雎使<b>于</b>秦。', '九年级下册｜《唐雎不辱使命》', '安陵君于是派唐雎出使到秦国。', 0, 0),
(1945, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '受地<b>于</b>先王。', '九年级下册｜《唐雎不辱使命》', '从先王那里继承这块土地。', 0, 0),
(1946, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '此所谓战胜<b>于</b>朝廷。', '九年级下册｜《邹忌讽齐王纳谏》', '这就是所说的在朝廷上取得胜利。', 0, 0),
(1947, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '箕畚运<b>于</b>渤海之尾。', '八年级上册｜《愚公移山》', '用箕畚装土石，运到渤海边上。', 0, 0),
(1948, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '指通豫南，达<b>于</b>汉阴‌。', '八年级上册｜《愚公移山》', '让道路一直通向豫州南部，最终延伸‌到汉水的南岸‌。', 0, 0),
(1949, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '困<b>于</b>心，衡<b>于</b>虑，而后作；征<b>于</b>色，发<b>于</b>声，而后喻。', '八年级上册｜《生于忧患，死于安乐》', '内心困惑，思虑堵塞，然后才能奋发；表现在脸色上，流露在言谈中，然后才能被人了解。', 0, 0),
(1950, 2, '于', 'yú', '<介>介绍动作行为发生时间、处所，可译为“在”、“到”、“从”等', '得复见将军<b>于</b>此。', '高中必修下册｜《鸿门宴》', '能够在这里再次见到将军。', 0, 0),
(1952, 2, '于', 'yú', '<介>介绍动作行为涉及的对象，可译为“对”、“向”等', '晋侯、秦伯围郑，以其无礼<b>于</b>晋，且贰<b>于</b>楚也。', '高中必修下册｜《烛之武退秦师》', '晋文公和秦穆公包围郑国，因为郑国曾对晋国无礼，并且在晋、楚之间摇摆。', 0, 0),
(1953, 2, '于', 'yú', '<介>介绍比较的对象，可译为“比”', '冰，水为之，而寒<b>于</b>水。', '高中必修上册｜《劝学》', '冰是水凝结而成的，却比水寒冷。', 0, 0),
(1954, 2, '于', 'yú', '<介>介绍比较的对象，可译为“比”', '长<b>于</b>臣。', '高中必修下册｜《鸿门宴》', '（他）比我年长。', 0, 0),
(1955, 2, '于', 'yú', '<介>介绍比较的对象，可译为“比”', '皆以美<b>于</b>徐公。', '九年级下册｜《邹忌讽齐王纳谏》', '都认为（我）比徐公美。', 0, 0),
(1956, 2, '于', 'yú', '<介>介绍比较的对象，可译为“比”', '所欲有甚<b>于</b>生者‌。', '九年级下册｜《鱼我所欲也》', '我所想要的，还有比生命更重要的东西。', 0, 0),
(1957, 2, '于', 'yú', '<介>介绍动作行为涉及的对象，可译为“对”、“向”等', '客之美我者，欲有求<b>于</b>我也。', '九年级下册｜《邹忌讽齐王纳谏》', '客人认为我美，是想要向我有所求。', 0, 0),
(1958, 2, '于', 'yú', '<介>介绍动作行为涉及的对象，可译为“对”、“向”等', '是臣尽节<b>于</b>陛下之日长。', '高中选择性必修下册｜《陈情表》', '这就是我向陛下尽忠尽节的日子长。', 0, 0),
(1959, 2, '于', 'yú', '<介>介绍动作行为的主动者，可译为“被”', '不拘<b>于</b>时。', '高中必修上册｜《师说》', '所以在内被郑袖迷惑，在外被张仪欺骗。', 0, 0),
(1960, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '学而时习<b>之</b>，不亦说乎？', '七年级上册｜《论语》十二章', '学习知识然后按时温习它，不也很愉快吗？', 0, 0),
(1961, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '愿陛下亲<b>之</b>信<b>之</b>。', '九年级下册｜《出师表》', '希望陛下亲近他们、信任他们。', 0, 0),
(1962, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '作《师说》以贻<b>之</b>。', '高中必修上册｜《师说》', '写这篇《师说》来赠送给他（李蟠）。', 0, 0),
(1963, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '輮使<b>之</b>然也。', '高中必修上册｜《劝学》', '用火烘烤使它变成这样。', 0, 0),
(1964, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '康肃笑而遣<b>之</b>。', '七年级下册｜《卖油翁》', '陈尧咨笑着打发他走了。', 0, 0),
(1965, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '具答<b>之</b>。', '八年级下册｜《桃花源记》', '（渔人）详细地回答他们。', 0, 0),
(1966, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '策<b>之</b>不以其道。', '八年级下册｜《马说》', '用马鞭驱赶它，不按照（驱使千里马的）正确方法。', 0, 0),
(1967, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '陈胜佐<b>之</b>，并杀两尉。', '九年级下册｜《陈涉世家》', '陈胜帮助他，一同杀死两个军官。', 0, 0),
(1968, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '屠暴起，以刀劈狼首，又数刀毙<b>之</b>。', '七年级上册｜《狼》', '屠户突然跳起，用刀砍狼的脑袋，又连砍几刀杀死它。', 0, 0),
(1969, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '复投<b>之</b>，后狼止而前狼又至。', '七年级上册｜《狼》', '又把骨头扔给狼，后得到骨头的狼停下，先前那只狼又跟上来。', 0, 0),
(1970, 2, '之', 'zhī', '<助>用在表示时间的副词后，补足音节，没有实义', '怅恨久<b>之</b>。', '九年级下册｜《陈涉世家》', '因失望而叹恨了很久。', 0, 0),
(1971, 2, '之', 'zhī', '<助>用在表示时间的副词后，补足音节，没有实义', '公将鼓<b>之</b>。', '九年级下册｜《曹刿论战》', '鲁庄公将要击鼓进军。', 0, 0),
(1972, 2, '之', 'zhī', '<助>用在表示时间的副词后，补足音节，没有实义', '久<b>之</b>，目似瞑，意暇甚。', '七年级下册｜《狼》', '过了很久，狼的眼睛好像闭上了，神情悠闲得很。', 0, 0),
(1973, 2, '之', 'zhī', '<助>用在表示时间的副词后，补足音节，没有实义', '鸣<b>之</b>而不能通其意。', '八年级下册｜《马说》', '它鸣叫，却不能通晓它的意思。', 0, 0),
(1975, 2, '之', 'zhī', '<代>第三人称代词，相当于“他”、“它”、“它们”、“他们”等', '千乘之国，摄乎大国之间，加<b>之</b>以师旅，因<b>之</b>以饥馑。', '高中必修下册｜《子路、曾皙、冉有、公西华侍坐》', '一个有一千辆兵车的国家，夹在大国的中间，又有军队侵犯它，接着发生饥荒。', 0, 0),
(1976, 2, '之', 'zhī', '<代>指示代词，相当于“这个”、“这”、“这种”等', '有良田、美池、桑竹<b>之</b>属。', '八年级下册｜《桃花源记》', '有肥沃的田地、美丽的池塘、桑树竹林这类景物。', 0, 0),
(1977, 2, '之', 'zhī', '<代>指示代词，相当于“这个”、“这”、“这种”等', '士大夫<b>之</b>族。', '高中必修上册｜《师说》', '士大夫这一类人。', 0, 0),
(1978, 2, '之', 'zhī', '<代>指示代词，相当于“这个”、“这”、“这种”等', '巫医乐师百工<b>之</b>人，不耻相师。', '高中必修上册｜《师说》', '巫医、乐师、各种工匠这一类人，不以互相学习为耻。', 0, 0),
(1979, 2, '之', 'zhī', '<代>指示代词，相当于“这个”、“这”、“这种”等', '宁越、徐尚、苏秦、杜赫<b>之</b>属为<b>之</b>谋。', '高中选择性必修中册｜《过秦论》', '宁越、徐尚、苏秦、杜赫这一类人替他们谋划。', 0, 0),
(1980, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '人知从太守游而乐，而不知太守<b>之</b>乐其乐也。', '九年级下册｜《醉翁亭记》', '人们只知道跟随太守游玩的快乐，却不知道太守以他们的快乐为快乐啊。', 0, 0),
(1981, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '王<b>之</b>蔽甚矣。', '九年级下册｜《邹忌讽齐王纳谏》', '大王您受蒙蔽太深了。', 0, 0),
(1982, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '吾妻<b>之</b>美我者，私我也。', '九年级下册｜《邹忌讽齐王纳谏》', '我的妻子认为我美，是偏爱我。', 0, 0),
(1983, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '妾<b>之</b>美我者，畏我也。', '九年级下册｜《邹忌讽齐王纳谏》', '妾认为我美，是害怕我。', 0, 0),
(1984, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '甚矣，汝<b>之</b>不惠。', '八年级下册｜《愚公移山》', '你太不聪明了！', 0, 0),
(1985, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '汝心<b>之</b>固，固不可彻。', '八年级下册｜《愚公移山》', '你思想顽固，顽固到了不可改变的地步。', 0, 0),
(1986, 2, '之', 'zhī', '<助>用在主谓之间，取消句子独立性，一般不必译出', '虽我<b>之</b>死，有子存焉。', '八年级下册｜《愚公移山》', '即使我死了，还有儿子在。', 0, 0),
